module.exports = [
{"id":"niupai","name":"牛排","category":"荤菜","categoryKey":"meat_dish","emoji":"🥩","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/牛排/牛排.jpg","hasImage":true,"difficulty":4,"difficultyText":"★★★★","calories":"1605 大卡","time":"","servings":"1-2人份","description":"这是一道经典的西式煎牛排，焦香外壳包裹着鲜嫩多汁的肉心，搭配黄油、大蒜和香草，风味浓郁。富含优质蛋白质、油脂及铁、锌等矿物质。烹饪流程对新手较为友好，但掌握火候仍需一些练习，全程 15-30 分钟即可完成。","tags":["进阶挑战"],"ingredients":[{"name":"牛排","amount":"450-500g（两片牛排）","optional":false,"amountValue":500,"amountUnit":"g"},{"name":"黑胡椒粉","amount":"2g","optional":false,"amountValue":2,"amountUnit":"g"},{"name":"盐","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"大蒜","amount":"1 个（约 25-30g，实际用量约为 5-10g）","optional":false,"amountValue":1,"amountUnit":"个"},{"name":"橄榄油","amount":"10-15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"黄油","amount":"20-25g","optional":false,"amountValue":25,"amountUnit":"g"},{"name":"口蘑","amount":"5-10 个","optional":false,"amountValue":10,"amountUnit":"个"},{"name":"小土豆","amount":"5-10 个（每个约 20g）","optional":false,"amountValue":10,"amountUnit":"个"},{"name":"小番茄","amount":"5-10 个（每个约 15g）","optional":false,"amountValue":10,"amountUnit":"个"},{"name":"百里香","amount":"2g（若使用新鲜百里香枝条，取 3-6 根，每根约 10cm 长即可）","optional":false,"amountValue":2,"amountUnit":"g"}],"steps":[{"text":"从冰箱中取出牛排解冻。","group":"备料"},{"text":"如果牛排处于冰冻状态，需提前一晚转移至冷藏室，并在烹饪前半小时放置在常温中。","group":"备料"},{"text":"**请勿**将牛排**置于水中或加热解冻**。","group":"备料"},{"text":"将小番茄，小土豆和口蘑洗净，对半切开备用。","group":"备料"},{"text":"将大蒜剥皮，留 5-8 个较大的蒜瓣，用刀背**压扁**备用。","group":"备料"},{"text":"牛排的预处理","group":"备料"},{"text":"对于肉眼牛排（见[如何选择不同种类的牛排](https://zhuanlan.zhihu.com/p/72352426)），使用厨房剪刀竖直插入到肉眼牛排中心的结缔组织，剪 1-2 刀。这是因为肉眼牛排的“肉眼”（即这块结缔组织）在高温下会剧烈收缩导致牛排变形，使得牛排无法均匀受热。","group":"备料"},{"text":"对于西冷牛排，如果您不喜欢西冷牛排边上的油脂，可以用刀慢慢将其剔除。","group":"备料"},{"text":"随后，使用厨房纸包裹牛排，将牛排上附着的水全部吸干，直至牛排放在案板上拿起后不留下明显水渍即可。","group":"备料"},{"text":"将炉灶打开高火（见附录对于火力大小的说明），同时锅中加入橄榄油，热锅 15-30 秒。","group":"烹饪"},{"text":"腌制牛排。将海盐和黑胡椒均匀的洒在牛排的全部表面并用手涂抹，揉搓，使得盐和胡椒颗粒尽量嵌入到肉中。注意，腌制完成后牛排**需要立即下锅，不推荐提前腌制牛排**。这是因为外表涂抹的盐会析出牛肉中的水分，影响烹饪的同时丧失风味。","group":"烹饪"},{"text":"热锅至油温 6-8 成（参见[油温判断技巧](./../../../tips/advanced/油温判断技巧.md)），将牛排由近及远的缓慢放入锅中。","group":"烹饪"},{"text":"如果您使用了土豆作为配菜，可以将土豆放入碗中，然后放进微波炉加热 10 分钟，或者放入开水煮 3-5 分钟。","group":"烹饪"},{"text":"单面煎制 1.5 分钟（这个时间适用于 2-3cm 厚大约的牛排。如果您的牛排更薄，考虑将这个时间缩短为 1 分钟。如果您的牛排更厚，考虑将这个时间增加至 2-2.5 分钟。）","group":"烹饪"},{"text":"翻面，再煎制 1.5 分钟。","group":"烹饪"},{"text":"对于西冷牛排和菲力牛排，您需要使用筷子或者锅铲将牛排竖起来，煎它的侧面约 30 秒。","group":"烹饪"},{"text":"将炉灶切换至中火，随后按顺序**快速加入**黄油、大蒜、百里香。用锅铲推动黄油在锅中快速涂抹直至完全融化。将大蒜压在牛排下以增加风味。","group":"烹饪"},{"text":"将平底锅**倾斜地放在灶上**，使得油全部流到锅的一侧。","group":"烹饪"},{"text":"将香料和大蒜放置在牛排上，用汤匙舀起锅中的油，不断地淋在牛排上。这个过程持续 30 秒，随后将牛排翻面，再重复这个过程 30 秒。","group":"烹饪"},{"text":"您可以通过观察油淋在牛排表面时的状态来判断当前的火候。如果油淋在牛排上时冒泡并且油的颜色没有变成深褐色，则油温合适。","group":"烹饪"},{"text":"如果您的牛排没有擦干净或使用了不推荐的方式解冻，或者使用盐进行了提前腌制，这个时候锅中会出现大量水，导致牛排最后是被“煮熟”的，从而丧失风味。","group":"烹饪"},{"text":"如果牛排表面出现大量的油泡并且油的颜色变成深褐色，则说明油温过高，您需要将锅移开灶台，稍等片刻再继续淋油。","group":"烹饪"},{"text":"将牛排盛出放在案板上，用锡箔纸包裹，等待 5-10 分钟。这个过程（称为醒肉）的作用是利用牛排自身的温度继续加热，锁住水分。","group":"烹饪"},{"text":"将配菜（土豆，番茄，蘑菇）倒入锅中，开中火煎 5 分钟。","group":"烹饪"},{"text":"取出牛排，用刀切成宽度 1.5cm 宽度的肉条，此时您可以观察到牛肉的熟度。","group":"烹饪"},{"text":"取出配菜，装盘，淋上锅中剩余的油或者牛排酱汁（可选）","group":"烹饪"}],"tips":["煎制牛排是控制火候的艺术。限于篇幅，这里简单给出一些定量评估火力的方法和本文中用到的与火候相关的术语。更多内容参见油温判断技巧。","对于电磁炉：","高火：功率 1.8Kw - 2.2kw。","中火：功率 800w - 1.4kw。","小火：功率 200w - 600w。","对于燃气灶：","高火：旋转气阀至最大出气速度的 70%-90%。","中火：旋转气阀至最大出气速度的 40%-60%。","小火：旋转气阀至最大出气速度的 10%-30%。","牛排的调味不一定需要遵循本指南的规范。通常来说，大蒜、黑胡椒和黄油是必须的，但如果您不喜欢迷迭香或百里香等唇形科植物等味道，您可以自由尝试其他牛排调味料进行调味。市面上也有售卖的多种烤肉调味盐可供选择。笔者曾发现一种中西结合的做法，即将小米辣切开与蒜片加入橄榄油中煎，并作为调味在最后淋到牛排上，也独具风味。"]},
{"id":"nongjiayiwanxiang","name":"农家一碗香","category":"荤菜","categoryKey":"meat_dish","emoji":"🍖","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/农家一碗香/农家一碗香成品.jpg","hasImage":true,"difficulty":3,"difficultyText":"★★★","calories":"1638 大卡","time":"","servings":"1人份","description":"这是一道咸香下饭的湖南家常小炒，五花肉的油润、鸡蛋的嫩滑与青椒的清香彼此融合，口感层次丰富。猪肉与鸡蛋提供优质蛋白质，搭配青椒补充维生素 C，营养均衡。中等难度，需要注意煸炒火候和调味顺序，新手稍加练习也能做好。预计备菜 7 分钟，烹饪 10 分钟，总共约 17 分钟就能出锅。","tags":[],"ingredients":[],"steps":[{"text":"备菜阶段：将猪肉切片，最好把肥瘦分开放。同时要把青椒和小米辣切成段，蒜片用刀背拍成末，姜切成丝。鸡蛋打到小碗中，用筷子打散。","group":""},{"text":"备好菜，就可正式煮菜了。先将油倒入锅中，锅中开小火，油热后将蛋液倒入锅中，将鸡蛋炒散，炒至断生即可，放回小碗中备用。","group":""},{"text":"将锅中继续加一点油，开小火，锅热后将之前切的肥猪肉倒入锅中逼出猪油。","group":""},{"text":"肥肉出现金黄色的时候，加大火力到中火，将瘦肉一起放入锅中翻炒。","group":""},{"text":"瘦肉全部炒至变色的时候加入备好的姜丝、蒜末和豆瓣酱翻炒均匀给猪肉上色。","group":""},{"text":"放入青红椒、炒至断生的鸡蛋后加入酱油和白糖，继续将它们翻炒到青椒微微断生，保持青椒清脆口感。","group":""},{"text":"出锅上菜！","group":""}],"tips":["+ 如果第一次炒鸡蛋的时候放的油太多，炒猪肉的时候可以视情况不加油。","+ 参考资料下厨房"]},
{"id":"pijiuya","name":"啤酒鸭","category":"荤菜","categoryKey":"meat_dish","emoji":"🦆","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/啤酒鸭/啤酒鸭.jpg","hasImage":true,"difficulty":4,"difficultyText":"★★★★","calories":"170 大卡","time":"1小时","servings":"1-2人份","description":"这是一道风味独特的家常菜肴，鸭肉鲜香软烂，透着淡淡啤酒清香，热而不浮、香而不腻。鸭肉富含蛋白质，啤酒去腥增香，搭配食用更有滋味。做法对新手友好，从备料到出锅大约需要 1 小时。","tags":["辣","进阶挑战"],"ingredients":[{"name":"鸭肉半只（约","amount":"1kg）","optional":false,"amountValue":1000,"amountUnit":"g"},{"name":"啤酒","amount":"800ml","optional":false,"amountValue":800,"amountUnit":"ml"},{"name":"生抽酱油","amount":"10-15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"老抽酱油","amount":"5-10ml","optional":false,"amountValue":10,"amountUnit":"ml"},{"name":"姜","amount":"5 片","optional":false,"amountValue":5,"amountUnit":"片"},{"name":"蒜头","amount":"12 瓣","optional":false,"amountValue":12,"amountUnit":"瓣"},{"name":"冰糖","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"干辣椒","amount":"5 个","optional":false,"amountValue":5,"amountUnit":"个"},{"name":"料酒","amount":"30ml","optional":false,"amountValue":30,"amountUnit":"ml"},{"name":"盐","amount":"8g","optional":false,"amountValue":8,"amountUnit":"g"},{"name":"鸡精","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"丁香","amount":"4 颗","optional":false,"amountValue":4,"amountUnit":"颗"},{"name":"八角","amount":"3 个","optional":false,"amountValue":3,"amountUnit":"个"},{"name":"香叶","amount":"3 片","optional":false,"amountValue":3,"amountUnit":"片"},{"name":"豆瓣酱","amount":"20g","optional":false,"amountValue":20,"amountUnit":"g"}],"steps":[{"text":"把鸭子切成 3 cm 小块，鸭肉冷水下锅，加姜片、料酒，焯一遍水，盛出沥干水分，备用。","group":""},{"text":"炒锅烧热，放入约 100ml 食用油，大火待油烧开，鸭肉入锅翻炒至上色。","group":""},{"text":"待鸭肉完全变色（肉眼可见泛白），将鸭肉拨到锅的一边，倒入豆瓣酱和糖，小火翻炒出香味和糖色。","group":""},{"text":"加入丁香、八角、香叶、干辣椒、生抽、老抽、蒜，翻炒出香味。","group":""},{"text":"倒入啤酒，没过鸭肉，加入盐、鸡精，然后中火将鸭子烧 30 分钟（牙口不好的话可以再多烧 5 分钟）。","group":""},{"text":"出锅盛盘，上桌食用。","group":""}],"tips":["啤酒的量一定要足够把所有鸭肉没过，啤酒最好选择清香型的。"]},
{"id":"qianshilachangwawacai","name":"黔式腊肠娃娃菜","category":"荤菜","categoryKey":"meat_dish","emoji":"🥬","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/黔式腊肠娃娃菜/黔式腊肠娃娃菜.jpg","hasImage":true,"difficulty":1,"difficultyText":"★","calories":"1030 大卡","time":"","servings":"1人份","description":"这道菜咸鲜可口，融合了黔式腊肠的醇香与娃娃菜的清甜，是西南菜系中少见的不辣风味，南北皆宜。娃娃菜富含维生素和膳食纤维，搭配腊肠的蛋白质与脂肪，营养均衡。制作过程极为简单，无需掌握火候和额外调味，从备料到出锅仅需 15 分钟，非常适合新手和忙碌的日常。","tags":["新手友好"],"ingredients":[{"name":"黔式腊肠","amount":"200g","optional":false,"amountValue":200,"amountUnit":"g"},{"name":"娃娃菜","amount":"300g","optional":false,"amountValue":300,"amountUnit":"g"},{"name":"水","amount":"750ml","optional":false,"amountValue":750,"amountUnit":"ml"}],"steps":[{"text":"锅内放入 750ml 水，开火加热至沸腾","group":""},{"text":"放入腊肠，计时 13 分钟","group":""},{"text":"放入娃娃菜，计时 2 分钟","group":""},{"text":"关火，夹出腊肠及娃娃菜","group":""},{"text":"娃娃菜切段、腊肠切片，装盘","group":""}],"tips":["根据锅的大小，建议以水量没过食材为宜，宁多勿少","如果没有刀具，娃娃菜和腊肠不切也可以"]},
{"id":"qingjiaoniang","name":"青椒酿","category":"荤菜","categoryKey":"meat_dish","emoji":"🌶","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/青椒酿/成品.jpeg","hasImage":true,"difficulty":3,"difficultyText":"★★★","calories":"1403 大卡","time":"","servings":"1-2人份","description":"这道广西经典家常菜以青椒包裹调好味的肉馅或虾滑，煎至表皮起皱呈虎皮色后焖煮入味，青椒清香与馅料鲜美交融，咸香微辣，十分下饭。猪肉和虾仁提供优质蛋白质，青椒富含维生素 C，营养均衡。制作需要一点耐心酿馅，但整体流程清晰，跟着步骤操作一般 30 分钟就能完成。","tags":[],"ingredients":[{"name":"青椒","amount":"8 个（约 400g，选笔直肉厚的尖椒）","optional":false,"amountValue":8,"amountUnit":"个"},{"name":"猪肉馅","amount":"250g（肥瘦比例 3:7）","optional":false,"amountValue":250,"amountUnit":"g"},{"name":"葱","amount":"2 根（约 30g）","optional":false,"amountValue":2,"amountUnit":"根"},{"name":"生姜","amount":"1 小块（约 10g）","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"生抽","amount":"30ml（其中 15ml 调馅，15ml 调酱汁）","optional":false,"amountValue":30,"amountUnit":"ml"},{"name":"老抽","amount":"5ml","optional":false,"amountValue":5,"amountUnit":"ml"},{"name":"食盐","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"食用油","amount":"30ml","optional":false,"amountValue":30,"amountUnit":"ml"},{"name":"淀粉","amount":"10g（可选，其中 5g 涂青椒内壁、5g 水淀粉勾芡）","optional":true,"amountValue":10,"amountUnit":"g"},{"name":"大蒜","amount":"4 瓣（可选，约 15g）","optional":true,"amountValue":4,"amountUnit":"瓣"},{"name":"蚝油","amount":"10ml（可选）","optional":true,"amountValue":10,"amountUnit":"ml"},{"name":"料酒","amount":"10ml（可选）","optional":true,"amountValue":10,"amountUnit":"ml"},{"name":"鸡蛋","amount":"1 个（可选）","optional":true,"amountValue":1,"amountUnit":"个"},{"name":"白胡椒粉","amount":"2g（可选）","optional":true,"amountValue":2,"amountUnit":"g"},{"name":"白糖","amount":"5g（可选）","optional":true,"amountValue":5,"amountUnit":"g"}],"steps":[{"text":"猪肉洗净剁成肉馅（或用绞肉机），姜切末，葱切葱花","group":"准备馅料"},{"text":"肉馅中加入姜末、葱花、生抽 15ml、老抽 5ml、食盐 3g，搅拌均匀","group":"准备馅料"},{"text":"可选加入：料酒 10ml、蚝油 10ml、鸡蛋 1 个、淀粉 5g、白胡椒粉 2g、白糖 5g","group":"准备馅料"},{"text":"朝一个方向搅拌肉馅至粘稠上劲，腌制 10 分钟","group":"准备馅料"},{"text":"青椒洗净，去蒂，用筷子小心挖去内部的籽和白筋，保持青椒完整不破","group":"处理青椒"},{"text":"可选在青椒内壁撒干淀粉约 5g，摇晃均匀，帮助肉馅粘附不脱落","group":"处理青椒"},{"text":"将腌好的肉馅用筷子或裱花袋塞入青椒中，尽量填满但不要太紧以防撑破","group":"酿入肉馅"},{"text":"全部酿好后备用","group":"酿入肉馅"},{"text":"碗中加入生抽 15ml、老抽 5ml、清水 100ml，搅拌均匀","group":"调酱汁"},{"text":"可选加入淀粉 5g，使汤汁更浓稠","group":"调酱汁"},{"text":"热锅，倒入 30ml 食用油，油温五六成热时放入酿好的青椒（肉面朝下先煎）","group":"煎制焖煮"},{"text":"中小火慢煎，翻面使青椒各面都煎至表皮起皱呈虎皮色，盛出备用","group":"煎制焖煮"},{"text":"锅留底油，可选放入蒜末爆香","group":"煎制焖煮"},{"text":"倒入调好的酱汁，烧开后放入煎好的青椒","group":"煎制焖煮"},{"text":"转中小火，盖上锅盖焖煮 5-8 分钟，至汤汁浓稠、青椒变软","group":"煎制焖煮"},{"text":"开盖大火收汁至汤汁油亮包裹青椒，即可出锅装盘","group":"煎制焖煮"},{"text":"虾仁 250g 去虾线，用刀背拍成虾泥（保留一定颗粒感，口感更好，直接买成品虾滑得了，买那种三角形的裱花一样直接塞进去）","group":"虾滑 fork 版本"},{"text":"虾滑馅调味：姜末 5g、食盐 2g、淀粉 5g、生抽 10ml","group":"虾滑 fork 版本"},{"text":"可选加入：料酒 5ml、白胡椒粉 1g、蛋清半个","group":"虾滑 fork 版本"},{"text":"朝一个方向搅拌至虾滑上劲，腌制 10 分钟","group":"虾滑 fork 版本"},{"text":"后续酿入、煎制、焖煮步骤与猪肉版本一致","group":"虾滑 fork 版本"},{"text":"虾滑易熟，焖煮时间可缩短至 4-5 分钟","group":"虾滑 fork 版本"}],"tips":["青椒选笔直的比弯的好塞馅料，肉厚的尖椒比薄皮的口感更好","馅料朝一个方向搅拌才能上劲，口感更 Q 弹","青椒内壁涂干淀粉是防粘的关键，煎时肉馅不会脱落","煎至虎皮色是风味来源，不要跳过","酱汁可依个人口味调整，喜欢更辣的可加桂林辣椒酱","虾滑和猪肉馅可以混合使用，比例随意，虾肉增加鲜甜，猪肉提供油脂香","汤汁拌饭极佳，不要收太干"]},
{"id":"qingjiaotudouchaorou","name":"青椒土豆炒肉","category":"荤菜","categoryKey":"meat_dish","emoji":"🍖","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/青椒土豆炒肉/青椒土豆炒肉.jpg","hasImage":true,"difficulty":3,"difficultyText":"★★★","calories":"1288 大卡","time":"","servings":"1-2人份","description":"青椒土豆炒肉是一道荤素搭配的家常小炒，口感鲜香脆嫩，酱香浓郁，特别下饭。土豆富含碳水化合物和维生素 C，青椒提供丰富的维生素 C 和膳食纤维，搭配猪肉的优质蛋白质，营养均衡。这道菜做法不复杂，对新手比较友好，从备料到出锅大约只需 1 小时。","tags":[],"ingredients":[{"name":"青椒","amount":"2 个（共约 200g）","optional":false,"amountValue":2,"amountUnit":"个"},{"name":"土豆","amount":"2 个（共约 300g）","optional":false,"amountValue":2,"amountUnit":"个"},{"name":"猪肉","amount":"200g","optional":false,"amountValue":200,"amountUnit":"g"},{"name":"葱","amount":"1 根（约 10g）","optional":false,"amountValue":1,"amountUnit":"根"},{"name":"姜","amount":"1 块（约 5g）","optional":false,"amountValue":1,"amountUnit":"块"},{"name":"蒜","amount":"3 瓣（约 12g）","optional":false,"amountValue":3,"amountUnit":"瓣"},{"name":"盐","amount":"7g","optional":false,"amountValue":7,"amountUnit":"g"},{"name":"酱油","amount":"6-10ml","optional":false,"amountValue":10,"amountUnit":"ml"},{"name":"食用油","amount":"10-15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"土豆淀粉","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"水","amount":"15g","optional":false,"amountValue":15,"amountUnit":"g"}],"steps":[{"text":"青椒去除根蒂切小块，土豆去皮切 2mm 薄片，猪肉切 4mm 薄片，葱横纵切 3mm 小段，姜蒜去皮拍散剁碎末；土豆淀粉加入约 15g 水搅拌均匀至水淀粉。","group":""},{"text":"起锅烧油，加热至 7 成热放入猪肉片，缓缓翻滚炒至去肉红色，加入约 3ml 酱油，翻炒肉片均匀上色，放入约 2g 盐。","group":""},{"text":"转 5 成油温，加入葱姜蒜炒 5 秒，然后加入土豆片，转 7 成油温均匀翻炒，加入约 5ml 酱油和 2g 盐，炒至土豆断生，表面轻微焦黄。","group":""},{"text":"转 8 成油温加入青椒，大火煸炒出锅气（有白烟冒出），反复均匀翻炒 1 分钟上色，最后在锅周围倒入水淀粉转 4 成火勾芡。","group":""},{"text":"在外观*呈粘稠状态*后关火，盛盘","group":""}],"tips":[]},
{"id":"qingzhengjueyu","name":"清蒸鳜鱼","category":"荤菜","categoryKey":"meat_dish","emoji":"🐟","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/清蒸鳜鱼/清蒸鳜鱼成品图.jpg","hasImage":true,"difficulty":3,"difficultyText":"★★★","calories":"359 大卡","time":"","servings":"2人份","description":"清蒸鳜鱼肉质细嫩，鲜甜本味突出，是讲究原汁原味的家常河鲜做法。鳜鱼富含优质蛋白和多种微量元素，易于消化吸收。处理时需小心鱼鳍，但整体步骤不复杂，新手稍加注意也能胜任。从备料到出锅，大约只需半小时。","tags":["辣","蒸"],"ingredients":[{"name":"鳜鱼","amount":"500g","optional":false,"amountValue":500,"amountUnit":"g"},{"name":"大葱","amount":"1 节","optional":false,"amountValue":null,"amountUnit":""},{"name":"小葱","amount":"2 根","optional":false,"amountValue":2,"amountUnit":"根"},{"name":"生抽","amount":"30g","optional":false,"amountValue":30,"amountUnit":"g"},{"name":"红辣椒","amount":"1 颗","optional":false,"amountValue":1,"amountUnit":"颗"},{"name":"姜片","amount":"3 片","optional":false,"amountValue":3,"amountUnit":"片"},{"name":"食用油","amount":"20ml","optional":false,"amountValue":20,"amountUnit":"ml"}],"steps":[{"text":"**食材处理**：","group":""},{"text":"鳜鱼从腹部切开，去除鱼鳃和内脏，打去鱼鳞，用到在表皮上刮去粘液（这一步也可让热心摊主处理）","group":""},{"text":"鳜鱼身上打上花刀，放姜片，有条件的可以放点猪油，装盘在下面垫一个筷子，便于蒸制时受热均匀","group":""},{"text":"大葱划开后去除中间的芯，只保留外面两层","group":""},{"text":"小葱划开备用","group":""},{"text":"红椒去除辣椒籽和里层辣椒肉备用","group":""},{"text":"将准备好的大葱、小葱、辣椒码在一起，切成丝泡在水里备用","group":""},{"text":"**炒制过程**：","group":""},{"text":"锅里加水，水量大一些，水热后放入鳜鱼，盖上锅盖，大火蒸制 8 - 10 分钟，蒸鱼四字窍门：汽大火足","group":""},{"text":"蒸鱼过程，另起一个过热油，油需要烧到冒烟","group":""},{"text":"蒸制结束后，倒掉蒸鱼的水，去除姜片，放上葱丝，浇上热油","group":""},{"text":"在倒入生抽或蒸鱼豉油即可上桌","group":""}],"tips":["**注意事项**：","1. 鳜鱼背部鱼鳍容易伤人，处理时候需要注意，最好用剪刀剪掉","2. 蒸制时间需要根据鱼的大小调整，蒸鱼的关键在于水多汽大火足"]},
{"id":"roubingdundan","name":"肉饼炖蛋","category":"荤菜","categoryKey":"meat_dish","emoji":"🥚","color":"#FFB3A7","light":"#FFF0ED","image":null,"hasImage":false,"difficulty":3,"difficultyText":"★★★","calories":"1124 大卡","time":"","servings":"1人份","description":"肉饼炖蛋是一道咸鲜滑嫩的传统家常菜，肉饼吸饱了酱汁，鸡蛋卧在其中，口感软嫩又下饭。它富含优质蛋白质和多种氨基酸，能很好地补充体力。做法十分简单，对厨房新手非常友好，从备料到出锅大约只需要 20 分钟。","tags":["辣","汤"],"ingredients":[{"name":"猪肉末","amount":"300g","optional":false,"amountValue":300,"amountUnit":"g"},{"name":"鸡蛋","amount":"2 个","optional":false,"amountValue":2,"amountUnit":"个"},{"name":"料酒","amount":"10ml","optional":false,"amountValue":10,"amountUnit":"ml"},{"name":"生抽","amount":"20ml","optional":false,"amountValue":20,"amountUnit":"ml"},{"name":"白胡椒粉","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"芝麻香油","amount":"10-15ml","optional":false,"amountValue":15,"amountUnit":"ml"}],"steps":[{"text":"在碗中加入猪肉末、料酒、生抽、白胡椒粉、鸡蛋和芝麻香油，搅拌均匀。","group":""},{"text":"将调好味的猪肉末铺在盘子里，肉末中间用勺子挖一个洞，往洞中打入 1 个鸡蛋。","group":""},{"text":"锅中加水至 1/4 高度，水烧开后，将盘子放入锅中，盖上锅盖，蒸 15 分钟。","group":""}],"tips":["在取出肉饼炖蛋时，注意盘子很烫，请小心操作。"]},
{"id":"shazhucai","name":"杀猪菜","category":"荤菜","categoryKey":"meat_dish","emoji":"🥓","color":"#FFB3A7","light":"#FFF0ED","image":null,"hasImage":false,"difficulty":4,"difficultyText":"★★★★","calories":"1657 大卡","time":"","servings":"2-3人份","description":"这是一道源自东北的经典炖菜，酸爽鲜香、暖心暖胃。酸菜富含乳酸菌和膳食纤维，排骨提供优质蛋白与钙质，血肠则能补充铁元素。制作时需要耐心处理血肠以防煮爆，对厨房新手有一定挑战。从备料到出锅，预计耗时约一小时。","tags":["辣","进阶挑战"],"ingredients":[{"name":"血肠","amount":"200 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"酸菜","amount":"500 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"排骨","amount":"400 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"料酒","amount":"10 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"蒜瓣","amount":"5 个","optional":false,"amountValue":5,"amountUnit":"个"},{"name":"姜粉","amount":"5 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"干辣椒","amount":"5 个","optional":false,"amountValue":5,"amountUnit":"个"},{"name":"香叶","amount":"2 片","optional":false,"amountValue":2,"amountUnit":"片"},{"name":"八角","amount":"1 个","optional":false,"amountValue":1,"amountUnit":"个"},{"name":"葱结","amount":"1 个","optional":false,"amountValue":1,"amountUnit":"个"},{"name":"香油","amount":"10 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"菜籽油","amount":"10 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"盐","amount":"5 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"蘸料：辣椒油","amount":"5 克、生抽 10 克、蒜蓉 5 克、香油 2 克。","optional":false,"amountValue":null,"amountUnit":""}],"steps":[{"text":"血肠用牙签多扎一些小孔，然后放水中小火煮十分钟，不要让水烧开，保持 80 度，否则血肠非常容易爆开。","group":""},{"text":"煮好的血肠切块备用。","group":""},{"text":"排骨放料酒焯水，控干水分备用。","group":""},{"text":"锅内放入菜籽油，放蒜瓣，干辣椒，姜粉炒香。","group":""},{"text":"放入排骨翻炒至表面金黄。","group":""},{"text":"酸菜洗净拧干水分，放入锅中，加入香油翻炒，香油可以更好的去除酸味而且让酸菜更香，大火翻炒二分钟。","group":""},{"text":"加入 600 毫升热水。","group":""},{"text":"转入电压力锅，加香叶，八角，葱结，盐。","group":""},{"text":"浓香模式压 40 分钟。","group":""},{"text":"到时间后放气开盖。加入血肠和枸杞，盖上锅盖焖二分钟即可，血肠是熟的，不需再加热。","group":""},{"text":"倒入盆中，按照上表调制蘸料，即可开吃。","group":""}],"tips":[]},
{"id":"shanxiguoyourou","name":"山西过油肉","category":"荤菜","categoryKey":"meat_dish","emoji":"🍖","color":"#FFB3A7","light":"#FFF0ED","image":null,"hasImage":false,"difficulty":4,"difficultyText":"★★★★","calories":"679 大卡","time":"40分钟","servings":"1人份","description":"过油肉是山西传统名菜，肉片滑嫩、蒜苔爽脆，咸鲜微酸，带着陈醋的醇香，属于典型的地方家常风味。猪里脊提供优质蛋白，搭配木耳、蒜苔和葱头，营养均衡。这道菜对火候和上浆技巧有一定要求，更适合有一定下厨基础的爱好者尝试。从备料到出锅，大约需要 40 分钟。","tags":["进阶挑战"],"ingredients":[{"name":"猪里脊","amount":"150 g","optional":false,"amountValue":150,"amountUnit":"g"},{"name":"蒜苔","amount":"6 根","optional":false,"amountValue":6,"amountUnit":"根"},{"name":"食用油","amount":"300ml","optional":false,"amountValue":300,"amountUnit":"ml"},{"name":"葱姜蒜","amount":"50g","optional":false,"amountValue":50,"amountUnit":"g"},{"name":"生抽","amount":"20ml","optional":false,"amountValue":20,"amountUnit":"ml"},{"name":"食盐","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"鸡蛋","amount":"1 个","optional":false,"amountValue":1,"amountUnit":"个"},{"name":"淀粉","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"木耳","amount":"20g","optional":false,"amountValue":20,"amountUnit":"g"},{"name":"葱头","amount":"100g","optional":false,"amountValue":100,"amountUnit":"g"},{"name":"其他调料","amount":"20g","optional":false,"amountValue":20,"amountUnit":"g"}],"steps":[{"text":"木耳提前泡发好，如果着急可以用热水泡发。","group":""},{"text":"猪里脊切片放入碗中，加 20ml 生抽、料酒、花椒粉，打入一个鸡蛋，拿自己的小手搅拌均匀，加入淀粉（建议红薯淀粉）拌匀，倒入 300ml 食用油封浆，腌制 15 分钟。","group":""},{"text":"蒜苔切段大约 3cm，葱头切菱形块备用。","group":""},{"text":"起锅烧油油要多一点，油温五成热，下入腌制好的肉片，将肉片打散，捞出控油备用。","group":""},{"text":"将锅中多余油倒出，留 10ml 油炒菜，油温七成热","group":""},{"text":"下入葱姜蒜爆香，先下蒜苔炒至断生，再下入木耳葱头，加入生抽，花椒粉，翻炒几下将之前炸好的肉片下入翻炒","group":""},{"text":"加 10g 的盐，起锅前加 10ml 的醋和鸡精，起锅装盘。","group":""}],"tips":["炸肉片时，表面微焦即可，注意控制火候。","起锅前也可以打个薄薄的水淀粉，口感更佳。"]},
{"id":"shangzhirou","name":"商芝肉","category":"荤菜","categoryKey":"meat_dish","emoji":"🍖","color":"#FFB3A7","light":"#FFF0ED","image":null,"hasImage":false,"difficulty":5,"difficultyText":"★★★★★","calories":"1621 大卡","time":"2.5小时","servings":"1-2人份","description":"商芝肉是陕西商县的传统风味菜，色泽红润，质地软嫩，肥而不腻，带有商芝独特的清香。猪肉提供优质蛋白和脂肪，蕨类蔬菜商芝则增添了膳食纤维和多种微量元素。这道菜工序繁琐，对刀工和火候均有要求，适合有一定烹饪基础的人挑战。从备料到成菜，全程大约需要 2.5 小时。","tags":["辣","汤","甜","进阶挑战"],"ingredients":[{"name":"带皮猪五花肉","amount":"500 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"商芝","amount":"50 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"葱","amount":"10 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"姜","amount":"2 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"八角","amount":"3 个","optional":false,"amountValue":3,"amountUnit":"个"},{"name":"蜂蜜","amount":"15 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"醋","amount":"5 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"料酒","amount":"15 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"味精","amount":"1.5 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"酱油","amount":"10 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"摊鸡蛋皮:一张约","amount":"15 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"精盐","amount":"1 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"鸡汤","amount":"200 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"芝麻油","amount":"10 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"熟猪油","amount":"2000 克（消耗约 60 克）","optional":false,"amountValue":null,"amountUnit":""}],"steps":[{"text":"将肉刮洗干净，入煮锅煮至六成熟（变色为白），捞出趁热用蜂蜜、醋涂抹肉皮。","group":""},{"text":"炒锅内放入熟猪油，用旺火烧至八成熟（约 200 度，油表有大量青烟，油状平静），将肉块皮朝下投入，炸至呈金红色时，捞入凉肉煮锅（之前煮完的煮锅）中泡软，放在案板上，切成三寸(10 cm)长、两分(0.6 cm)厚的片，仍然皮朝下，整齐装入蒸碗内。","group":""},{"text":"将 5 克大葱切成 2.4 cm 长的段，5 克切成 2.4 cm 长的斜形片。姜去皮洗净，1.5 克切成片，5 克切成末，摊的鸡蛋皮切成 2.4 cm 长的等腰三角形片。","group":""},{"text":"商芝入沸水锅中煮软捞出，去除老茎、杂质，淘洗干净，切成 3 cm 长的段，放入碗中,加酱油（5 克）、精盐（1 克）、熟猪油（10 克）拌匀，盖在肉片上，另将鸡汤（100 克）放入一小碗中，加酱油（5 克）、精盐（0.5 克）、料酒（15 克）搅匀，浇入蒸碗，再放入姜片、葱段、八角上笼用旺火蒸约半小时后，转用小火继续蒸约一小时三十分钟，熟烂后取出，拣去姜、葱、八角，倒、过滤原汁，将肉扣入汤盘。","group":""},{"text":"炒锅内，放入鸡汤（100 克），加入原汁，用旺火烧沸，下入姜末、葱片、味精后搅匀，投入摊鸡蛋皮，淋芝麻油，浇入汤盘即成。","group":""}],"tips":["商芝属于小地方不特别有名的特产，至少本人在其他地方没有见到过，在制作时可换成其他蕨类蔬菜。"]},
{"id":"shouroutudoupian","name":"瘦肉土豆片","category":"荤菜","categoryKey":"meat_dish","emoji":"🍖","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/瘦肉土豆片/瘦肉土豆片.jpg","hasImage":true,"difficulty":3,"difficultyText":"★★★","calories":"585 大卡","time":"","servings":"1人份","description":"一道快手家常小炒，肉片滑嫩，土豆片软韧入味，带有蒜苗清香，属于典型的家常菜风格。瘦肉富含优质蛋白质和铁质，土豆提供碳水化合物和膳食纤维，搭配均衡。制作流程简单明了，需注意刀工和火候，适合有一定基础的新手尝试。从备料到出锅，预计 大约 1 小时即可完成。","tags":[],"ingredients":[{"name":"纯瘦肉","amount":"200g","optional":false,"amountValue":200,"amountUnit":"g"},{"name":"土豆","amount":"200g","optional":false,"amountValue":200,"amountUnit":"g"},{"name":"蒜苗","amount":"2 根（约 20 g）","optional":false,"amountValue":2,"amountUnit":"根"},{"name":"生粉","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"生抽","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"老抽","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"食用盐","amount":"2g","optional":false,"amountValue":2,"amountUnit":"g"}],"steps":[{"text":"土豆去皮、对半切开，再切成约 2mm 的薄片，备用","group":""},{"text":"蒜苗洗净，切成约 1cm 的段，备用","group":""},{"text":"瘦肉洗净切成约 2mm 的薄片，放入碗中，加入 5g 生粉、5g 生抽、3g 老抽腌制十分钟，备用","group":""},{"text":"瘦肉腌制时，烧一锅开水，将土豆片放入锅中，焯水，约 5 分钟","group":""},{"text":"热锅，锅内放入 10ml - 15ml 食用油。等待 10 秒让油温升高","group":""},{"text":"放入瘦肉，翻炒至变色，倒入蒜苗一起炒，蒜苗炒约 20 秒","group":""},{"text":"放入土豆，保持翻炒，加入 2g 食用盐、5g 生抽，","group":""},{"text":"炒约 3 分钟，盛盘","group":""}],"tips":["土豆片焯水注意不宜太久，防止土豆片变软","腌制瘦肉要搅拌均匀"]},
{"id":"shuizhuniurou","name":"水煮牛肉","category":"荤菜","categoryKey":"meat_dish","emoji":"🥩","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/水煮牛肉/sznr1.jpg","hasImage":true,"difficulty":3,"difficultyText":"★★★","calories":"431 大卡","time":"","servings":"1人份","description":"水煮牛肉是川菜中的经典麻辣味型，口感滑嫩、汤汁红亮、香辣烫鲜。牛肉富含优质蛋白质和铁，搭配豆芽可补充膳食纤维。这道菜对新手来说不算太难，但需注意火候和泼油安全，整体制作约需四十分钟。","tags":["辣"],"ingredients":[{"name":"牛肉","amount":"300g","optional":false,"amountValue":300,"amountUnit":"g"},{"name":"豆芽","amount":"100g","optional":false,"amountValue":100,"amountUnit":"g"},{"name":"鸡蛋","amount":"1 个","optional":false,"amountValue":1,"amountUnit":"个"},{"name":"香菜","amount":"5 根","optional":false,"amountValue":5,"amountUnit":"根"},{"name":"豆瓣酱","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"料酒","amount":"10ml","optional":false,"amountValue":10,"amountUnit":"ml"},{"name":"淀粉","amount":"15g","optional":false,"amountValue":15,"amountUnit":"g"},{"name":"干辣椒粉","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"姜","amount":"20g","optional":false,"amountValue":20,"amountUnit":"g"},{"name":"蒜","amount":"3 瓣","optional":false,"amountValue":3,"amountUnit":"瓣"},{"name":"红辣椒","amount":"1 根","optional":false,"amountValue":1,"amountUnit":"根"},{"name":"蚝油","amount":"8g","optional":false,"amountValue":8,"amountUnit":"g"}],"steps":[{"text":"牛肉洗干净切片。","group":""},{"text":"加入 15g 姜丝，1 个鸡蛋，15g 淀粉，8g 蚝油，10ml 料酒搅拌均匀，腌制 15 分钟。","group":""},{"text":"香菜洗干净切好。","group":""},{"text":"锅里倒油，加入豆瓣酱，5g 姜丝，蒜片。","group":""},{"text":"倒入开水，煮成红汤。","group":""},{"text":"豆芽洗干净去掉尾须，放进开水里焯熟。","group":""},{"text":"将豆芽铺入碗底。","group":""},{"text":"将牛肉片一片一片的放进红汤中，煮熟以后捞出。","group":""},{"text":"将牛肉铺在豆芽上，撒上香菜梗。","group":""},{"text":"撒上香菜叶，辣椒粉，辣椒圈。","group":""},{"text":"另起锅烧热油，将热油淋在菜上面，就完成了。","group":""}],"tips":["参考: 水煮牛肉的详细步骤"]},
{"id":"shuizhuroupian","name":"水煮肉片","category":"荤菜","categoryKey":"meat_dish","emoji":"🍖","color":"#FFB3A7","light":"#FFF0ED","image":null,"hasImage":false,"difficulty":5,"difficultyText":"★★★★★","calories":"361 大卡","time":"","servings":"1人份","description":"水煮肉片是一道麻辣鲜香、肉片滑嫩、配菜爽脆的经典川菜，极其适合下饭。猪里脊提供优质蛋白质，搭配豆芽等蔬菜，营养均衡。做法稍显繁琐，尤其需要耐心腌制肉片和制作刀口辣椒，新手大约需要 1 至 2 小时完成。","tags":["辣","进阶挑战"],"ingredients":[{"name":"里脊肉的用量为","amount":"300g","optional":false,"amountValue":300,"amountUnit":"g"},{"name":"小葱","amount":"2 根","optional":false,"amountValue":2,"amountUnit":"根"},{"name":"生姜","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"大蒜","amount":"20g","optional":false,"amountValue":20,"amountUnit":"g"},{"name":"红泡椒","amount":"20g（根据受辣程度选择 0-40 g）","optional":false,"amountValue":20,"amountUnit":"g"},{"name":"蒜苗","amount":"2 根","optional":false,"amountValue":2,"amountUnit":"根"},{"name":"芹菜","amount":"3 根","optional":false,"amountValue":3,"amountUnit":"根"},{"name":"红油瓣酱","amount":"5ml","optional":false,"amountValue":5,"amountUnit":"ml"},{"name":"鸡精","amount":"1.5g","optional":false,"amountValue":1.5,"amountUnit":"g"},{"name":"生抽酱油","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"食用盐","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"胡椒粉","amount":"2g","optional":false,"amountValue":2,"amountUnit":"g"},{"name":"料酒","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"鸡蛋清","amount":"1 个","optional":false,"amountValue":1,"amountUnit":"个"},{"name":"土豆淀粉","amount":"7g","optional":false,"amountValue":7,"amountUnit":"g"},{"name":"植物油","amount":"280g（根据情况选择，想吃重油就多加 100g）","optional":false,"amountValue":280,"amountUnit":"g"},{"name":"菜籽油","amount":"200g（根据情况选择，想吃重油就多加 100g）","optional":false,"amountValue":200,"amountUnit":"g"},{"name":"绿豆芽","amount":"100g","optional":false,"amountValue":100,"amountUnit":"g"},{"name":"凤尾","amount":"1 根","optional":false,"amountValue":1,"amountUnit":"根"},{"name":"白砂糖","amount":"1g","optional":false,"amountValue":1,"amountUnit":"g"},{"name":"小米辣干辣椒","amount":"20g（根据受辣程度选择 0-40g）","optional":false,"amountValue":20,"amountUnit":"g"},{"name":"青花椒","amount":"5g（根据情况选择，想吃麻就多 5g）","optional":false,"amountValue":5,"amountUnit":"g"}],"steps":[{"text":"里脊肉改刀成小块，再切成 2 毫米薄片（可根据自己的口感改进），放入碗中，加入清水清洗两遍来去除血水和杂质，捞出挤干水分备用。","group":""},{"text":"碗中加入食用盐 1.5g，胡椒粉 1g，生抽酱油 5g，料酒 3g，然后朝着一个方向搅拌 2 分钟，使其入味。","group":""},{"text":"另外准备一个碗，加入一个鸡蛋清，加入 7g 土豆淀粉，一个方向搅拌均匀，倒入肉中","group":""},{"text":"再次一个方向搅拌均匀（肉表面就形成了润滑膜，这样会使肉更加鲜嫩）","group":""},{"text":"最后再加入 30g 植物油轻轻搅拌（防止肉片粘连）。","group":""},{"text":"绿豆芽 100g，凤尾 1 根（改刀成小条），芹菜 3 根切成小段，蒜苗 2 根拍散切成小段。","group":""},{"text":"大蒜 20g 剁碎，生姜小块剁碎，红泡椒 20g 剁碎。","group":""},{"text":"小米辣干辣椒 15g，青花椒 3g，锅内加入油滑锅，油稍许热了将多余的倒出备用留 50g 底油，下入干辣椒、花椒，开小火炒香，切记不要炒糊（颜色要变黑即可），倒出在菜板上剁细。","group":""},{"text":"锅烧热，放入 100g 植物油烧至 6 成热，加入 2g 青花椒、干辣椒爆香，配菜下锅，加入 1g 食用盐，炒至断生，盛入碗中垫底备用。","group":""},{"text":"锅洗干净，加入 150g 植物油烧至 6 成热，加入制作好的姜蒜红泡椒，爆香后加入豆瓣 10g，开小火把豆瓣爆香炒出红油即可。","group":""},{"text":"加入 800 毫升清水（根据实际情况选择），大火烧开，转小火调味，加入食用盐 2.5g，鸡精 1.5g，1g 白砂糖提鲜，1g 胡椒粉，5g 水淀粉（根据实际情况选择）将汤汁收浓稠一点。","group":""},{"text":"汤汁开后，开小火将腌制好的肉片分开依次下锅，然后开中火将肉片烫熟，用锅铲轻轻推动一下避免粘连，待汤汁烧开，肉片熟后捞出放入碗中配菜上，再将原汤倒入（不超过菜品）。","group":""},{"text":"碗中均匀撒上刀口辣椒、蒜蓉和葱花。","group":""},{"text":"锅洗干净，加入 200g 菜籽油，烧至 7 成热，然后一次性均匀泼在碗中肉片上（注意安全），美味完成。","group":""}],"tips":["垫底的蔬菜根据自己口味选择（蘑菇、白菜、油麦菜等）。","刀口辣椒制作嫌麻烦也可以直接用干辣椒段和青花椒代替。","特别注意肉的腌制（搅拌的时候朝着一个方向、血水处理干净），保证肉滑嫩（鸡蛋清、淀粉搅拌均匀）。","水煮牛肉也可以按照这个做法。","美食作家王刚R"]},
{"id":"suantaichaoroumo","name":"蒜苔炒肉末","category":"荤菜","categoryKey":"meat_dish","emoji":"🍖","color":"#FFB3A7","light":"#FFF0ED","image":null,"hasImage":false,"difficulty":2,"difficultyText":"★★","calories":"258 大卡","time":"","servings":"1人份","description":"蒜苔炒肉末是北方家常菜，咸鲜脆嫩，蒜香浓郁。蒜苔富含膳食纤维和维生素，五花肉提供蛋白质，荤素搭配均衡。做法简单，备料轻松，新手也能快速上手。从切配到出锅大约只需 10 分钟。","tags":["新手友好"],"ingredients":[{"name":"蒜苔","amount":"1 扎（每扎蒜苔约 190g）","optional":false,"amountValue":190,"amountUnit":"g"},{"name":"五花肉薄片","amount":"4 片（约 20g）","optional":false,"amountValue":4,"amountUnit":"片"},{"name":"食用油","amount":"10ml","optional":false,"amountValue":10,"amountUnit":"ml"},{"name":"蒜瓣","amount":"2 瓣","optional":false,"amountValue":2,"amountUnit":"瓣"},{"name":"生抽","amount":"15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"食盐","amount":"2g","optional":false,"amountValue":2,"amountUnit":"g"}],"steps":[{"text":"蒜苔切成 5cm 小段，备用","group":""},{"text":"五花肉切成 5mm * 5cm 丝状，备用","group":""},{"text":"蒜瓣拍碎切成末，备用","group":""},{"text":"热锅，锅内放入 10ml 食用油。等待 10 秒让油温升高","group":""},{"text":"放入蒜末，中火翻炒 **10 秒** 将蒜末炒出香味","group":""},{"text":"放入五花肉和 5ml 生抽，中火翻炒 **30 秒** 将肉炒熟并上色","group":""},{"text":"将蒜苔放入锅内并加入 10ml 生抽，翻炒 **30 秒**","group":""},{"text":"锅内加入 20g 水，中火翻炒 **5 分钟** 将蒜苔炒至稍稍变软","group":""},{"text":"最后加入 2g 食盐，中火翻炒 **30 秒**，即可出锅装盘","group":""}],"tips":["加入食盐前可尝一下咸淡，自行决定是否增减盐量","选用五花肉薄片是因为切肉简单且不用腌制即可入味"]},
{"id":"taishiluroufan","name":"台式卤肉饭","category":"荤菜","categoryKey":"meat_dish","emoji":"🍖","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/台式卤肉饭/1.jpg","hasImage":true,"difficulty":3,"difficultyText":"★★★","calories":"1495 大卡","time":"","servings":"2-3人份","description":"台式卤肉饭是一道浓香四溢的台湾家常料理，肉条软糯入味，酱汁琥珀般油亮，浇在热米饭上满口脂香。富含优质蛋白、胶原蛋白和碳水，能快速补充能量。做法对新手非常友好，只需备好食材、掌握火候，全程约 1.5 小时即可完成，其中动手操作仅需半小时，剩下的交给小火慢炖。","tags":["下饭"],"ingredients":[{"name":"红葱头","amount":"25 g","optional":false,"amountValue":25,"amountUnit":"g"},{"name":"带皮五花肉","amount":"500g","optional":false,"amountValue":500,"amountUnit":"g"},{"name":"鸡蛋","amount":"4 个（可任意修改鸡蛋个数）","optional":false,"amountValue":4,"amountUnit":"个"},{"name":"食用油","amount":"15 ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"生抽酱油","amount":"75 ml","optional":false,"amountValue":75,"amountUnit":"ml"},{"name":"米酒","amount":"10 + 25 ml","optional":false,"amountValue":25,"amountUnit":"ml"},{"name":"大蒜","amount":"25 g","optional":false,"amountValue":25,"amountUnit":"g"},{"name":"香叶","amount":"2 片","optional":false,"amountValue":2,"amountUnit":"片"},{"name":"八角","amount":"1 颗","optional":false,"amountValue":1,"amountUnit":"颗"},{"name":"冰糖","amount":"20 g","optional":false,"amountValue":20,"amountUnit":"g"},{"name":"白胡椒粉","amount":"6 g","optional":false,"amountValue":6,"amountUnit":"g"},{"name":"五香粉","amount":"6 g","optional":false,"amountValue":6,"amountUnit":"g"},{"name":"米饭 （根据个人食量决定）","amount":"","optional":false,"amountValue":null,"amountUnit":""}],"steps":[{"text":"带皮五花肉切成 $0.7cm（长）\\times 0.7cm（宽） \\times 2.5cm（高）$ 的细长条","group":""},{"text":"红葱头、大蒜切末备用","group":""},{"text":"鸡蛋煮熟剥壳，并用刀划破蛋白（便于入味），备用。","group":""},{"text":"**大火**热锅，锅内放入 15 ml 食用油，让油滑满锅底即可。","group":""},{"text":"放油的目的是防止五花肉刚下锅时粘锅。等待 5s 使油温稍微升高。","group":""},{"text":"放入五花肉条，翻炒至肉色稍微变白，沿锅边淋入米酒 10ml 。继续翻炒至五花肉不再出油。","group":""},{"text":"将切好的红葱头加入锅中，翻炒 1 分钟爆出油葱香味。","group":""},{"text":"将切好的红葱头加入锅中，翻炒 30 秒。","group":""},{"text":"把猪肉推到旁边，放入冰糖加热到融化冒泡变成焦糖，再把猪肉一起翻拌，让焦糖均匀附着。","group":""},{"text":"加入生抽炒出香气。","group":""},{"text":"呛入米酒 25 ml ，水加到淹过猪肉，加入白胡椒粉、五香粉、八角、香叶、水煮蛋，沸腾后转小火卤 1 小时。","group":""},{"text":"注意: 不同酱油的咸淡不一，卤的时候务必试味道，太甜加酱油，太咸加点糖或水调整。","group":""},{"text":"小火炖煮过程中，每隔 15 分钟 搅拌检查一次，防止粘锅。","group":""},{"text":"如发现过干，则可加入 100ml 清水继续炖煮。","group":""},{"text":"1 小时后，开大火收汁直到酱汁浓稠，呈现有光泽的琥珀色，即完成。","group":""},{"text":"炖煮结束后，乘一碗米饭，将软烂的卤肉浇在米饭上，并加上卤蛋，开始享用。","group":""}],"tips":["对于五花肉切条步骤，定义：五花肉带皮面向上摆在桌上，此时肉皮所在平面为长宽形成的平面，垂直此平面的为高。肉条最终效果是肥瘦相间的细长条。（注意：此处肉条一定要细，即长宽较小。细肉条更易于炖煮软糯）。","五花肉切条小技巧：","若五花肉是**未冷冻**的，可以放入冰箱**冷冻室 30 分钟** 再取出切条。","若是**冷冻五花肉**，可以在**常温**下放置 **30 分钟** 后再切条。","切条时可以较小的力度将刀刃与肉快速摩擦，如此更易于切割并保护五花肉肥瘦相间的结构。"]},
{"id":"tangculiji","name":"糖醋里脊","category":"荤菜","categoryKey":"meat_dish","emoji":"🍬","color":"#FFB3A7","light":"#FFF0ED","image":null,"hasImage":false,"difficulty":4,"difficultyText":"★★★★","calories":"1573 大卡","time":"45分钟","servings":"1-2人份","description":"糖醋里脊酸甜浓郁、外酥里嫩，是广受欢迎的家常风味，在多地域菜系中都很常见。猪里脊提供优质蛋白，但裹粉油炸和糖醋汁使整体热量偏高。制作时需要掌握腌制、复炸和调汁火候，对新手稍有挑战，建议提前备好料并一气呵成。从备料到出锅大约需要 45 分钟到 1 小时。","tags":["进阶挑战"],"ingredients":[{"name":"里脊肉","amount":"500g","optional":false,"amountValue":500,"amountUnit":"g"},{"name":"醋","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"白糖","amount":"30g","optional":false,"amountValue":30,"amountUnit":"g"},{"name":"淀粉","amount":"50g","optional":false,"amountValue":50,"amountUnit":"g"},{"name":"鸡蛋","amount":"50g","optional":false,"amountValue":50,"amountUnit":"g"},{"name":"生抽","amount":"10ml","optional":false,"amountValue":10,"amountUnit":"ml"},{"name":"料酒","amount":"20g","optional":false,"amountValue":20,"amountUnit":"g"},{"name":"蚝油","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"番茄酱","amount":"30ml","optional":false,"amountValue":30,"amountUnit":"ml"},{"name":"白胡椒粉","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"食盐","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"}],"steps":[{"text":"腌肉：将猪里脊肉先切厚片，用刀背拍一拍，把肉拍松一点。切成一个手指头粗的条，加料酒，生抽，蚝油，食盐，白胡椒粉，一个鸡蛋，将肉用手抓匀，腌制 20 分钟以上。","group":""},{"text":"调酱：番茄酱+10g 醋+30g 白糖+150ml 清水，搅拌至糖融化，备用。","group":""},{"text":"裹粉：先把粉全部裹好再来炸，这样在炸的时候就不会手忙脚乱。准备一个大碗，里面放淀粉，把每一根肉条都满满裹上淀粉。","group":""},{"text":"炸制：油温 160 摄氏度下里脊，可以拿一个干筷子放在油里面试一下，周围冒小泡就可以下锅。","group":""},{"text":"炸到表面微黄可以捞出，全程中火。然后等油温升高到 200 摄氏度，把里脊倒进去重新炸一次，只需 40 秒，表皮就会很脆，马上捞出。","group":""},{"text":"裹酱：另外拿一个锅，锅里放底油，把调好的酱汁倒进去，煮到冒泡，把炸好的里脊放进去，翻炒，让每一根都裹上酱汁。","group":""},{"text":"下炸好的里脊肉翻炒，关火盛出。","group":""}],"tips":["里脊要多炸几遍，注意火候，否则达不到外焦里嫩的效果！","下厨房","百度百科"]},
{"id":"tangcupaigu","name":"糖醋排骨","category":"荤菜","categoryKey":"meat_dish","emoji":"🍬","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/糖醋排骨/1.jpeg","hasImage":true,"difficulty":4,"difficultyText":"★★★★","calories":"1022 大卡","time":"","servings":"1-2人份","description":"糖醋排骨是一道酸甜可口、外酥里嫩的传统名菜，广受欢迎。排骨富含优质蛋白和钙质，有较好的滋补效果。这道菜涉及焯水、油炸、炒糖色和收汁等多个步骤，对火候和调味有一定要求，不算特别适合新手，但按照优化后的流程操作成功率较高。预计制作时长为 大约 45 分钟。","tags":["辣","进阶挑战"],"ingredients":[{"name":"排骨","amount":"300 g","optional":false,"amountValue":300,"amountUnit":"g"},{"name":"白砂糖","amount":"30 g","optional":false,"amountValue":30,"amountUnit":"g"},{"name":"食用油","amount":"300–350 ml  （油量需根据锅具大小调整，如用于深炸则以足以覆盖排骨 2/3 为准）","optional":false,"amountValue":350,"amountUnit":"ml"},{"name":"生抽","amount":"5 ml","optional":false,"amountValue":5,"amountUnit":"ml"},{"name":"蚝油","amount":"5 ml","optional":false,"amountValue":5,"amountUnit":"ml"},{"name":"老抽","amount":"5 ml","optional":false,"amountValue":5,"amountUnit":"ml"},{"name":"鸡精","amount":"2 g","optional":false,"amountValue":2,"amountUnit":"g"},{"name":"姜片","amount":"2 片","optional":false,"amountValue":2,"amountUnit":"片"},{"name":"芝麻","amount":"2 g","optional":false,"amountValue":2,"amountUnit":"g"},{"name":"番茄酱","amount":"10 g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"香醋","amount":"5 ml","optional":false,"amountValue":5,"amountUnit":"ml"},{"name":"五香粉","amount":"0.5 g","optional":false,"amountValue":0.5,"amountUnit":"g"}],"steps":[{"text":"排骨与姜片放入冷水中，大火加热至水沸腾、出现大量泡沫后转中火，待水持续沸腾时再转小火焯水 2–3 分钟，捞出备用。","group":""},{"text":"用开水反复清洗排骨 2–3 遍，确保彻底去除血沫。","group":""},{"text":"在锅中倒入足够量的食用油进行深炸（油量依据锅具大小而定，建议约 300 ml 供一般家庭使用），待油温升至约 170°C 后，下排骨炸制 3–5 分钟，直至表面略呈金黄色，捞出控油。","group":""},{"text":"另取干净锅，置于小火上加热 50 ml 热水，加入白砂糖 30 g，轻轻搅拌直至糖完全溶解，并略呈淡黄色。此步骤的重点在于观察糖溶解情况，无需过分依赖颜色变化。","group":""},{"text":"将炸好的排骨倒入炒制糖水的锅中，迅速翻炒 30 秒后，依次加入香醋 5 ml、生抽 5 ml、蚝油 5 ml、鸡精 2 g、番茄酱 10 g、五香粉 0.5 g，再次翻炒 30 秒，使调料均匀裹覆排骨，然后加入开水至刚好没过排骨。","group":""},{"text":"用大火将锅中液体煮沸后，加入老抽 5 ml 进行上色，并快速收汁；若排骨块较大，可转小火焖煮 5–10 分钟以便更好地入味，切勿采用中火长时间炖煮 20 分钟，以免损伤口感。","group":""},{"text":"起锅装盘，撒上芝麻 2 g，即可享用。","group":""}],"tips":["炸排骨时可根据实际情况轻撒少量干淀粉于排骨表面，以提升酥脆口感。","焯水时注意火力变化：冷水下锅后先用大火至水沸腾、泡沫丰富，再转中火，最后转小火焯水；焯水后应使用开水清洗，避免因温差过大导致肉质变柴。","步骤四的关键在于确保白糖完全溶解，无须过分依赖颜色变化判断。","收汁时应快速翻炒，使排骨均匀裹上调料，避免长时间煮炖造成口感损失。"]},
{"id":"tianluoniang","name":"田螺酿","category":"荤菜","categoryKey":"meat_dish","emoji":"🐚","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/田螺酿/成品.jpeg","hasImage":true,"difficulty":4,"difficultyText":"★★★★","calories":"533 大卡","time":"","servings":"2-3人份","description":"田螺酿是阳朔“十八酿”之首，螺肉韧而紧致、猪肉嫩滑，紫苏薄荷清香扑鼻，曾登上《舌尖上的中国 2》。富含蛋白质和多种微量元素，螺肉与猪肉搭配营养互补。这道菜步骤稍多，对新手有一定挑战，需提前半天让田螺吐沙，正式制作约 40 分钟，适合节假日全家一起动手。","tags":["辣","进阶挑战"],"ingredients":[{"name":"大田螺","amount":"20 个（约 1000g）","optional":false,"amountValue":20,"amountUnit":"个"},{"name":"猪肉","amount":"250g","optional":false,"amountValue":250,"amountUnit":"g"},{"name":"新鲜薄荷叶","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"紫苏叶","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"生姜","amount":"1 小块（约 15g）","optional":false,"amountValue":15,"amountUnit":"g"},{"name":"葱","amount":"2 根（约 30g）","optional":false,"amountValue":2,"amountUnit":"根"},{"name":"桂林三花酒","amount":"15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"生抽","amount":"30ml（其中 15ml 调馅、15ml 调味汤汁）","optional":false,"amountValue":30,"amountUnit":"ml"},{"name":"食盐","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"食用油","amount":"30ml","optional":false,"amountValue":30,"amountUnit":"ml"},{"name":"酸笋","amount":"50g（可选）","optional":true,"amountValue":50,"amountUnit":"g"},{"name":"大蒜","amount":"5 瓣（可选，约 20g）","optional":true,"amountValue":5,"amountUnit":"瓣"},{"name":"干辣椒","amount":"4 个（可选）","optional":true,"amountValue":4,"amountUnit":"个"},{"name":"蚝油","amount":"10ml（可选）","optional":true,"amountValue":10,"amountUnit":"ml"},{"name":"淀粉","amount":"10g（可选）","optional":true,"amountValue":10,"amountUnit":"g"},{"name":"白胡椒粉","amount":"2g（可选）","optional":true,"amountValue":2,"amountUnit":"g"}],"steps":[{"text":"上午买回田螺，放入清水盆中，静置一下午吐沙","group":"吐沙（提前半天）"},{"text":"可在水中滴几滴香油（或者芥末~）加速吐沙","group":"吐沙（提前半天）"},{"text":"用刷子将田螺外壳刷洗干净（这一步可以时间久一些）","group":"处理田螺"},{"text":"用老虎钳或菜刀剪去田螺尾部（约剪掉 1/3 到一半）","group":"处理田螺"},{"text":"大锅烧水，水开后放入田螺焯烫 1-2 分钟（时间不可太久，螺肉会老）","group":"处理田螺"},{"text":"捞出后用牙签挑出螺肉，去掉螺盖和黑色泥肠","group":"处理田螺"},{"text":"螺壳用水冲洗干净，甩干水分备用","group":"处理田螺"},{"text":"螺肉用盐抓洗干净，剁成碎粒（不要剁成泥，保留颗粒感才有嚼头）","group":"制作馅料"},{"text":"猪肉剁成肉末","group":"制作馅料"},{"text":"薄荷叶、紫苏叶切碎，姜切末，葱切葱花","group":"制作馅料"},{"text":"将螺肉碎、猪肉末、薄荷碎、紫苏碎、姜末、葱花放入碗中","group":"制作馅料"},{"text":"加入三花酒 15ml、生抽 15ml、食盐 3g","group":"制作馅料"},{"text":"可选加入：蚝油 10ml、白胡椒粉 2g、淀粉 10g","group":"制作馅料"},{"text":"朝一个方向搅拌至馅料粘稠上劲","group":"制作馅料"},{"text":"图省事上面的所有东西直接放入打肉机直接打。","group":"制作馅料"},{"text":"将馅料用筷子塞入田螺壳中，尽量塞满塞紧，但不要撑破螺壳","group":"酿制"},{"text":"依次酿完所有田螺","group":"酿制"},{"text":"热锅，倒入 30ml 食用油，可选放入酸笋和干辣椒炒出香味","group":"焖煮"},{"text":"倒入清水或高汤约 300ml，加生抽 15ml、食盐 2g，大火烧开","group":"焖煮"},{"text":"将酿好的田螺放入锅中，盖上锅盖，中小火焖煮 10 分钟","group":"焖煮"},{"text":"焖煮过程中不要频繁翻动，等肉馅六七成熟定型后再轻轻翻动","group":"焖煮"},{"text":"开盖，放入剩余的新鲜薄荷叶和紫苏叶，再焖 2-3 分钟","group":"焖煮"},{"text":"大火收汁至汤汁浓稠，即可出锅","group":"焖煮"}],"tips":["食用方法：先吮吸壳内汤汁，再用牙签挑出或用嘴猛吸出肉馅——\"嗦螺贴唇猛吸气\"","螺肉和猪肉最佳比例为 1:1","薄荷是这道菜的精华，紫苏配田螺是绝配，两者至少要有其一","没有三花酒可用料酒代替，但风味会打折扣","焯水时间一定要短，久了螺肉变老发硬","搭配冰镇漓泉啤酒是阳朔当地的标准吃法","参考资料：阳朔田螺酿_百度百科"]},
{"id":"tianlakaoquanchi","name":"甜辣烤全翅","category":"荤菜","categoryKey":"meat_dish","emoji":"🍮","color":"#FFB3A7","light":"#FFF0ED","image":null,"hasImage":false,"difficulty":3,"difficultyText":"★★★","calories":"775 大卡","time":"","servings":"1人份","description":"这道甜辣烤全翅利用空气炸锅烹制，外皮微焦、内里多汁，甜中带辣的风味很受欢迎。鸡肉富含优质蛋白质，用空气炸代替油炸大幅减少了油脂，吃起来负担更轻。制作流程清晰明了，只需提前腌制并中途翻面一次，对新手也比较友好。从处理食材到出锅大约需要 3 个小时，大部分是静置腌制的时间，实际操作并不繁琐。","tags":["辣","烤","甜"],"ingredients":[{"name":"鸡全翅","amount":"4 个","optional":false,"amountValue":4,"amountUnit":"个"},{"name":"生抽","amount":"45ml","optional":false,"amountValue":45,"amountUnit":"ml"},{"name":"老抽","amount":"15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"蒜粉","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"胡椒粉","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"糖","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"甜椒粉","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"辣椒粉","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"蚝油","amount":"15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"水","amount":"20ml","optional":false,"amountValue":20,"amountUnit":"ml"},{"name":"油","amount":"10ml","optional":false,"amountValue":10,"amountUnit":"ml"}],"steps":[{"text":"将 4 个新鲜鸡全翅取出，在翅中两根骨头之间用刀划开表皮，正反面各一刀","group":""},{"text":"将 4 个鸡全翅放入碗中，加入生抽 45ml ， 老抽 15ml ， 蒜粉 10g ， 胡椒粉 5g ， 糖 10g ， 甜椒粉 10g ，辣椒粉 5g ， 蚝油 15ml ， 水 20ml 以及油 10ml","group":""},{"text":"用勺子将酱汁均匀的抹在鸡全翅上，尤其是翅中的刀口处，大约花费 3 分钟","group":""},{"text":"用保鲜膜盖住防油腌制中鸡全翅的碗，放入冰箱冷藏格静置 120 分钟","group":""},{"text":"取出鸡全翅，锡纸盘中放入鸡全翅 4 个，将碗中残余酱料均匀倒在鸡全翅上","group":""},{"text":"锡纸盘放入空气炸锅的烤篮上，用 200 摄氏度烤 25 分钟","group":""},{"text":"打开空气炸锅，小心取出锡纸盘，将鸡全翅翻面","group":""},{"text":"继续 200 摄氏度烤 25 分钟","group":""},{"text":"取出即可食用","group":""}],"tips":["本例中鸡全翅口感为微辣，需增加辣度请增加辣椒粉用量，但不宜超过 30g","鸡全翅指包含翅尖，翅中和翅根的鸡翅","本品效果微焦，如不喜欢焦褐色外观可 不向锡纸盘中倒入残余酱汁并 每面只烤制 20 分钟","实际烤制效果请根据自己空气炸锅的功率判断","甜椒粉起增加色泽和风味作用，本身不能作为辣味剂","腌制时间可自由掌控，建议在 60 分钟到 180 分钟之间为宜","刚出锅的锡纸盘比较烫，请用夹子夹取或使用湿抹布之类的隔热材料拿取"]},
{"id":"tudoudunpaigu","name":"土豆炖排骨","category":"荤菜","categoryKey":"meat_dish","emoji":"🥔","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/土豆炖排骨/排骨1.jpg","hasImage":true,"difficulty":3,"difficultyText":"★★★","calories":"991 大卡","time":"","servings":"2-3人份","description":"排骨软烂脱骨，土豆绵软入味，酱香浓郁微甜微辣，是一道典型的北方家常炖菜。富含蛋白质、钙质和碳水化合物，营养均衡。制作略有难度，需掌握炒糖色与火候，但步骤清晰，新手也能尝试，全程大约 1.5 小时。","tags":["辣","汤"],"ingredients":[{"name":"肋排","amount":"750g","optional":false,"amountValue":750,"amountUnit":"g"},{"name":"土豆","amount":"300g","optional":false,"amountValue":300,"amountUnit":"g"},{"name":"姜","amount":"30g （分为两份：15g 焯水用，15g 炒制用）","optional":false,"amountValue":30,"amountUnit":"g"},{"name":"小葱","amount":"25g （分为两份：15g 打成葱结，10g 切葱花）","optional":false,"amountValue":25,"amountUnit":"g"},{"name":"料酒","amount":"25ml （分为两份：15ml 焯水用，10ml 炒制用）","optional":false,"amountValue":25,"amountUnit":"ml"},{"name":"白糖","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"干辣椒","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"八角","amount":"1g （约 1-2 颗）","optional":false,"amountValue":1,"amountUnit":"g"},{"name":"花椒","amount":"1g （约 10 粒）","optional":false,"amountValue":1,"amountUnit":"g"},{"name":"桂皮","amount":"1g （一小块）","optional":false,"amountValue":1,"amountUnit":"g"},{"name":"生抽","amount":"10ml","optional":false,"amountValue":10,"amountUnit":"ml"},{"name":"老抽","amount":"5ml","optional":false,"amountValue":5,"amountUnit":"ml"},{"name":"蚝油","amount":"5ml","optional":false,"amountValue":5,"amountUnit":"ml"},{"name":"黄豆酱","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"盐","amount":"3g （最后收汁调味用）","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"开水","amount":"700ml","optional":false,"amountValue":700,"amountUnit":"ml"},{"name":"食用油","amount":"20ml","optional":false,"amountValue":20,"amountUnit":"ml"}],"steps":[{"text":"**处理土豆：** 将 300g 土豆去皮，切成不规则的滚刀块 。**切好后立刻泡入一盆清水中**，隔绝氧气防止表面氧化发黑，备用。","group":"预处理：食材切配与防氧化"},{"text":"**处理葱姜：** 将 30g 姜全部切成薄片（分成两份 15g）。将 25g 小葱处理好：15g 挽成一个葱结，剩余 10g 切成细小葱花备用。","group":"预处理：食材切配与防氧化"},{"text":"**封装酱汁碗（一键调用）：** 拿一个小碗，依次加入 10ml 生抽、5ml 老抽、5ml 蚝油、5ml 黄豆酱，彻底搅拌均匀，放在灶台触手可及处备用。","group":"预处理：调料封装与异步任务"},{"text":"**封装香料碟（一键调用）：** 拿一个小碟，放入 5g 干辣椒、1g 八角（约 1-2 颗）、1g 花椒（约 10 粒）、1g 桂皮（一小块），以及刚才切好的 15g 姜片，备用。","group":"预处理：调料封装与异步任务"},{"text":"**开启异步水程：** 按下电热水壶开关，开始烧制 700ml 开水。（确保炒制完成时，开水刚好就绪）。","group":"预处理：调料封装与异步任务"},{"text":"**冷水焯水：** 将 750g 肋排冷水下锅，加入 15g 葱结、15g 姜片、15ml 料酒。大火煮沸后，继续保持沸腾焯水 2 分钟，逼出内部血沫。","group":"初步加工：排骨焯水与脱水"},{"text":"**热洗冷防：** 捞出排骨，**必须用热水**将排骨表面残留的浮沫清洗干净（遇冷水肉质会剧烈收缩变硬）。","group":"初步加工：排骨焯水与脱水"},{"text":"**绝对脱水（防爆防溅）：** 洗净的排骨**必须用厨房纸彻底吸干表面水分**，装盘放在炒锅旁边备用（防止后续下入高温糖色时发生剧烈炸锅）。","group":"初步加工：排骨焯水与脱水"},{"text":"**炒制糖色：** 热锅凉油，加入 20ml 食用油。将 10g 白糖倒入锅中，中小火不停搅拌。翻炒至白糖完全融化冒泡，并呈现红棕色的焦糖色 。","group":"核心炒制：糖色与爆香（高并发阶段）"},{"text":"**上色煎制：** 迅速加入彻底脱水的 750g 排骨，转中大火翻炒。煎制约 2-3 分钟，至排骨两面微微金黄，且均匀裹满焦糖色。","group":"核心炒制：糖色与爆香（高并发阶段）"},{"text":"**一键爆香：** 在锅中拨出一小块空地，**直接倒入【香料碟】**。利用锅底的热油爆香约 10 秒，激发出香料的脂溶性香气。","group":"核心炒制：糖色与爆香（高并发阶段）"},{"text":"**一键调味：** 顺着热锅边缘淋入剩余的 10ml 料酒激发出锅气。紧接着**直接倒入【酱汁碗】**，翻炒约 30 秒，让酱料完全包裹排骨并炒出浓郁酱香。","group":"核心炒制：糖色与爆香（高并发阶段）"},{"text":"**加水长炖：** 此时电热水壶已沸腾，直接加入 700ml 滚烫的开水（水量需没过排骨），大火烧开。随后盖上锅盖，转小火持续焖煮 40 分钟。","group":"炖煮收汁：挂霜与出锅"},{"text":"**加入土豆：** 40 分钟后打开锅盖，将泡在水里的 300g 土豆捞出沥干，下入锅中。重新盖上锅盖，继续小火焖煮 15-20 分钟，直到用筷子能轻松扎透土豆块。","group":"炖煮收汁：挂霜与出锅"},{"text":"**调味收汁：** 打开锅盖，加入 3g 盐（此时可尝一下汤汁，根据个人口味酌情微调）。转大火开始翻炒收汁，大约需要 3-5 分钟。直到汤汁变得浓稠，均匀地挂在排骨和土豆上即可关火。","group":"炖煮收汁：挂霜与出锅"},{"text":"**点缀出锅：** 盛盘出锅，在表面均匀撒上预处理好的 10g 葱花作为 UI 点缀即可。","group":"炖煮收汁：挂霜与出锅"}],"tips":[]},
{"id":"wugujizhua","name":"无骨鸡爪","category":"荤菜","categoryKey":"meat_dish","emoji":"🍗","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/无骨鸡爪/无骨鸡爪.jpg","hasImage":true,"difficulty":5,"difficultyText":"★★★★★","calories":"815 大卡","time":"","servings":"1人份","description":"酸辣开胃、口感 Q 弹，是一道家常凉拌小吃。鸡爪富含胶原蛋白，对皮肤有益。去骨步骤繁琐费力，制作难度较高，不太适合新手尝试。全程耗时约 8 小时 15 分钟。","tags":["辣","进阶挑战"],"ingredients":[{"name":"鸡爪","amount":"1kg","optional":false,"amountValue":1000,"amountUnit":"g"},{"name":"姜","amount":"4 片","optional":false,"amountValue":4,"amountUnit":"片"},{"name":"料酒","amount":"65g","optional":false,"amountValue":65,"amountUnit":"g"},{"name":"大葱","amount":"3 段（5cm 一段）","optional":false,"amountValue":3,"amountUnit":"段"},{"name":"大蒜","amount":"10 瓣","optional":false,"amountValue":10,"amountUnit":"瓣"},{"name":"小米辣","amount":"4 个少辣，6 个中辣，12 个大辣（推荐大辣）","optional":false,"amountValue":4,"amountUnit":"个"},{"name":"洋葱 （半个）","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"生抽 75g","amount":"15g * 5","optional":false,"amountValue":15,"amountUnit":"g"},{"name":"蚝油 30g","amount":"15g * 2","optional":false,"amountValue":15,"amountUnit":"g"},{"name":"黑醋（推荐陈醋）","amount":"50g","optional":false,"amountValue":50,"amountUnit":"g"},{"name":"白糖","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"盐","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"花椒油","amount":"10ml","optional":false,"amountValue":10,"amountUnit":"ml"},{"name":"香菜","amount":"3 颗","optional":false,"amountValue":3,"amountUnit":"颗"},{"name":"柠檬","amount":"2 颗（以 1 颗为单位来调整酸度）","optional":false,"amountValue":2,"amountUnit":"颗"}],"steps":[{"text":"用剪刀 / 刀 把鸡爪上的指甲的部分全部剪掉 **包括指甲下面的肉和骨头，让它一点指甲都不剩**","group":"鸡爪处理"},{"text":"用水把他们洗干净，放一边","group":"鸡爪处理"},{"text":"把`鸡爪`放入大锅中，准备去腥味","group":"鸡爪处理"},{"text":"`大葱`，`料酒`，`姜` 全放进去","group":"鸡爪处理"},{"text":"加水没过`鸡爪`","group":"鸡爪处理"},{"text":"大火煮开 **中途可以把浮末捞起来**","group":"鸡爪处理"},{"text":"水开**100度，沸腾**后等 10 分钟","group":"鸡爪处理"},{"text":"关火，捞出来，把水沥干，洗干净，放入盆里","group":"鸡爪处理"},{"text":"放入冰箱，**冷冻层** 20 分钟","group":"去骨"},{"text":"把全部放入不是冷冻层的冰箱，然后分批**10个一批**拿出来去骨","group":"去骨"},{"text":"从手指（鸡爪的）最前端开始，每只手指都要用刀划开**划到它的手背部分**","group":"去骨"},{"text":"再从手背部用刀分划开至整个手臂","group":"去骨"},{"text":"把每只手指关节处都掰一掰**按手指出声音时那种**","group":"去骨"},{"text":"按着它的手指最前端，往里推，每只手指都一样，先推到中间手掌手背部分","group":"去骨"},{"text":"每只手指皮脱离后，从手掌开始往手臂部分推直到整个脱下来了","group":"去骨"},{"text":"放入碗中，备用","group":"去骨"},{"text":"`小米辣` 切均匀小颗","group":"调配腌料"},{"text":"`大蒜`，`洋葱`，`香菜`切碎","group":"调配腌料"},{"text":"`柠檬`对半切开，把柠檬汁挤入鸡爪的容器里","group":"调配腌料"},{"text":"把`全部`调料倒入装鸡爪的容器，`小米辣`，`大蒜`，`洋葱`和`香菜`也放进去","group":"调配腌料"},{"text":"抓拌均匀","group":"调配腌料"},{"text":"放入冰箱一个晚上（6 个小时）","group":"调配腌料"},{"text":"调配好后全部放入准备好的鸡爪","group":"调配腌料"}],"tips":["操作时，需要注意观察沸腾的水位线，如发现低于 3/4 的食材应加热水至没过食材。","鸡爪去骨教程 ：bili_89324373958"]},
{"id":"xihongshiniunan","name":"西红柿牛腩","category":"荤菜","categoryKey":"meat_dish","emoji":"🥩","color":"#FFB3A7","light":"#FFF0ED","image":null,"hasImage":false,"difficulty":5,"difficultyText":"★★★★★","calories":"1569 大卡","time":"90分钟","servings":"1-2人份","description":"西红柿牛腩汤汁浓厚酸甜可口，牛肉软绵醇香，是道开胃下饭的家常菜。富含蛋白质、维生素和番茄红素，营养均衡。对新手有一定挑战，需要掌握炖肉火候和番茄炒汁的技巧。一般初学者大约需要 90 分钟完成。","tags":["进阶挑战"],"ingredients":[{"name":"西红柿","amount":"3-4 个（每个约 200g）","optional":false,"amountValue":4,"amountUnit":"个"},{"name":"牛腩","amount":"500g","optional":false,"amountValue":500,"amountUnit":"g"},{"name":"食用油","amount":"20-30ml","optional":false,"amountValue":30,"amountUnit":"ml"}],"steps":[{"text":"牛腩切条、切块成长宽高均 2cm ，冷水下锅，开锅煮制 2 分钟去除血水，捞出冲洗干净","group":""},{"text":"另起锅 2L 水烧开，加入 2cm 两段葱段、两片姜片、八角、料/黄酒 5-10ml，放入焯好的牛肉，盖盖炖制（砂锅 1 小时，高压锅炖肉模式 45 分钟），筷子能轻松插透就证明炖好了","group":""},{"text":"西红柿去皮：西红柿头部滑十字至腰线，筷子/刀叉从果蒂捅入，煤气灶小火，一边转动一边烤，及时拿下来查看，起皮后撕下来，切块。越小越好","group":""},{"text":"撕皮小心烫，去皮后的西红柿特别滑，慢切注意安全","group":""},{"text":"起锅烧油，油温 7 成热，葱、姜各 10g，番茄下锅，炒透炒出番茄红色，加入煮好的牛腩和原汤，原汤刚刚没过牛肉即可","group":""},{"text":"根据个人口味放入盐、糖、生抽调味盖盖","group":""},{"text":"开锅后大火继续炒制 3-5 分钟","group":""},{"text":"待番茄汁呈中等粘稠程度后关火，散入葱花，盛盘","group":""}],"tips":["用火注意安全、用火注意安全、用火注意安全","用砂锅/铝锅炖肉时，水开后转中小火/小火，使用高压锅见学习使用压力锅","教程中的番茄去皮方式是目前为止本人实践最快的方式","绝对不用番茄酱和少加佐料，尽可能还原食材的原味"]},
{"id":"xihongshitudoudunniurou","name":"西红柿土豆炖牛肉","category":"荤菜","categoryKey":"meat_dish","emoji":"🥩","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/西红柿土豆炖牛肉/abaaba_1.png","hasImage":true,"difficulty":4,"difficultyText":"★★★★","calories":"827 大卡","time":"","servings":"1人份","description":"一道家常炖菜，酸甜开胃，汤汁浓郁，牛肉软烂，土豆绵密。牛肉提供优质蛋白，西红柿富含番茄红素，搭配土豆和洋葱，营养均衡。操作简单，无需复杂技巧，新手也能轻松上手。从备菜到出锅大约需要 1 至 1.5 小时。","tags":["辣","汤","进阶挑战"],"ingredients":[{"name":"牛肉","amount":"500-700g","optional":false,"amountValue":700,"amountUnit":"g"},{"name":"小料","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"葱一根，姜四片，料酒","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"花椒","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"八角一个（半）","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"香叶两片","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"油","amount":"15ml （若用牛腩可根据喜好减少为 10ml）","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"调味品","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"白糖 or 冰糖","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"酱油（千禾酿造生抽无添加），老抽","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"黑胡椒粉（白的也行）2g","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"土豆两三个（看喜好，锅能盛了为准）","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"西红柿拳头大小中等个头两三个","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"比拳头大一点的洋葱一个","amount":"","optional":false,"amountValue":null,"amountUnit":""}],"steps":[{"text":"备菜:","group":""},{"text":"土豆去皮、切成 5cm 大块，备用","group":""},{"text":"西红柿切十字花刀，开水烫后去皮，把中间的芯去掉，切 3cm 小块备用","group":""},{"text":"葱切 4g 的葱花出来，剩下的掰成 5-8cm 大段","group":""},{"text":"牛肉泡凉水半小时去血水，或凉水下锅煮至表面变白捞出，期间撇去浮末","group":""},{"text":"洋葱切 0.5-1cm 小粒","group":""},{"text":"制作","group":""},{"text":"全程中火","group":""},{"text":"凉水没过牛肉，放入高压锅，放入葱段，姜片，放入 20g 料酒，上汽压 20 分钟","group":""},{"text":"取出牛肉后，切 5cm 大块，挑出姜，汤盛到一个大碗里一会炖煮用","group":""},{"text":"倒油，油四到五成热以后下花椒八角香叶，出香味之后糊之前挑出不用","group":""},{"text":"下入牛肉，葱姜，炒香，炒多久都无所谓，看着有点要糊可以舀 10ml 汤，此下同理","group":""},{"text":"炒香后加入生抽 15ml，料酒 15ml，胡椒粉，5-10g 番茄膏番茄酱或一个番茄罐头，加入洋葱炒至透明","group":""},{"text":"（可选）可以加一点点盐使洋葱出水不容易糊，不要加太多，后面再调味","group":""},{"text":"加入西红柿炒至西红柿化开软烂，倒入剩下的汤","group":""},{"text":"炖煮","group":""},{"text":"中火开锅后，全程小火","group":""},{"text":"出锅前 30-40 分钟 加土豆并调味","group":""},{"text":"依据个人口味边尝边加糖盐，合适为止","group":""},{"text":"筷子戳牛肉软烂后出锅！","group":""}],"tips":["炖煮时保证汤加入的时候是温热的","炖煮时不要扣盖否则土豆会烂","炖煮时时不时翻动避免糊底","砂锅炖煮会更好吃，可以在炒锅里炒完倒到煮锅里炖，如果用砂锅开锅之前不要用大火避免裂开","酱油总量不要太多，汤汁浓缩的时候会变咸，稀的时候稍微淡点没事，炖煮时候觉得不够也可以再加酱油","不要用鸡精味精，会抢夺牛肉的鲜味"]},
{"id":"xiangcunpijiuya","name":"乡村啤酒鸭","category":"荤菜","categoryKey":"meat_dish","emoji":"🦆","color":"#FFB3A7","light":"#FFF0ED","image":null,"hasImage":false,"difficulty":4,"difficultyText":"★★★★","calories":"1324 大卡","time":"","servings":"1人份","description":"鸭肉与啤酒同炖，汤汁浓郁，肉质鲜香软烂，还带有一股淡淡的啤酒清香，是一道风味独特的家常菜。鸭肉本身滋补，富含蛋白质、B 族维生素和多种矿物质，搭配啤酒炖煮后更易入味。这道菜步骤虽稍多，但操作并不复杂，一般初学者只需 大约 1 小时即可完成。","tags":["辣","进阶挑战"],"ingredients":[{"name":"鸭肉（半只,1 kg,让市场老板剁成小块）","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"啤酒","amount":"1000 ml （可以买 500 ml 的罐装啤酒两瓶）","optional":false,"amountValue":1000,"amountUnit":"ml"},{"name":"青椒","amount":"2 条，红椒 1 条 （ 长度 10 厘米到 15 厘米 之间都可以）（切段 或者切片都可以， 2 厘米一段）","optional":false,"amountValue":2,"amountUnit":"条"},{"name":"大蒜","amount":"4 颗 ,拍散备用","optional":false,"amountValue":4,"amountUnit":"颗","group":"辅料"},{"name":"生姜","amount":"3 厘米长，拍散备用","optional":false,"amountValue":null,"amountUnit":"","group":"辅料"},{"name":"小米辣","amount":"3 颗，切两段即可(不吃辣的可以不用","optional":false,"amountValue":3,"amountUnit":"颗","group":"辅料"},{"name":"蒜苗","amount":"2 根 切段备用","optional":false,"amountValue":2,"amountUnit":"根","group":"辅料"},{"name":"大葱","amount":"2 根  1 根切段,1 根备用","optional":false,"amountValue":2,"amountUnit":"根","group":"辅料"},{"name":"草果 两颗，拍散去仔备用","amount":"","optional":false,"amountValue":null,"amountUnit":"","group":"香料"},{"name":"桂皮","amount":"4 厘米一小片","optional":false,"amountValue":null,"amountUnit":"","group":"香料"},{"name":"八角","amount":"3 颗","optional":false,"amountValue":3,"amountUnit":"颗","group":"香料"},{"name":"香叶","amount":"3 片","optional":false,"amountValue":3,"amountUnit":"片","group":"香料"},{"name":"干辣椒","amount":"6 条 (不吃辣可以不用","optional":false,"amountValue":6,"amountUnit":"条","group":"香料"}],"steps":[{"text":"鸭肉清洗一遍放进锅中","group":"鸭肉焯水以去腥去血水"},{"text":"加清水淹没鸭肉","group":"鸭肉焯水以去腥去血水"},{"text":"加 20 ml 料酒","group":"鸭肉焯水以去腥去血水"},{"text":"加备用的 1 根 大葱","group":"鸭肉焯水以去腥去血水"},{"text":"加生姜 ,拍散的 2 厘米","group":"鸭肉焯水以去腥去血水"},{"text":"开火烧滚","group":"鸭肉焯水以去腥去血水"},{"text":"捞出浮沫","group":"鸭肉焯水以去腥去血水"},{"text":"鸭肉捞出，清水洗干净备用","group":"鸭肉焯水以去腥去血水"},{"text":"锅清洗干净烧热，加 60ml 的花生油","group":"开始煮"},{"text":"油温到 60 度的时候，加一把花椒（ 30 颗）","group":"开始煮"},{"text":"加鸭肉翻炒 4 分钟","group":"开始煮"},{"text":"2 分钟后加入所有的香料","group":"开始煮"},{"text":"3 分钟的时候加入所有的料头（生姜，大蒜，小米辣）","group":"开始煮"},{"text":"加入 1000 ml 的啤酒","group":"开始煮"},{"text":"烧鸭肉 30 分钟","group":"开始煮"},{"text":"10 分钟的时候加 盐 （3 克） 生抽( 10 ml ) 老抽( 5 ml)","group":"开始煮"},{"text":"20 分钟 加入所有的辅料 （青椒和红椒段）","group":"开始煮"},{"text":"29 分钟加入 蒜苗段 和 大葱段","group":"开始煮"},{"text":"翻炒 1 分钟","group":"开始煮"},{"text":"出锅","group":"开始煮"}],"tips":["操作时，需要注意观察沸腾的水位线，如发现低于 2/3 的食材应加热水或者加啤酒。","厨师长：用土灶烧“乡村啤酒鸭”，味道安逸得不摆了"]},
{"id":"xiangganqincaichaorou","name":"香干芹菜炒肉","category":"荤菜","categoryKey":"meat_dish","emoji":"🍖","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/香干芹菜炒肉/香干芹菜炒肉.jpg","hasImage":true,"difficulty":3,"difficultyText":"★★★","calories":"741 大卡","time":"","servings":"1-2人份","description":"香干芹菜炒肉是一道家常小炒，豆干柔韧、芹菜爽脆、猪肉嫩滑，咸鲜微辣。芹菜富含膳食纤维，豆干和猪肉提供优质植物蛋白与动物蛋白。做法简单，对新手友好，从备料到出锅大约只需 30 分钟。","tags":["辣"],"ingredients":[{"name":"豆干：150g","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"香芹：4 根","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"猪肉：200g","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"蒜头：2 瓣","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"辣椒：4 个","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"花椒：6 粒（不喜欢可以不放，或者放花椒水）","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"盐：5g","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"鸡精：3g","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"老抽：8ml","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"蚝油：5ml","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"食用油：10-15ml","amount":"","optional":false,"amountValue":null,"amountUnit":""}],"steps":[{"text":"芹菜去叶切段、切成不超过 4cm 的条状，备用","group":""},{"text":"香干切条，宽约小拇指，备用","group":""},{"text":"蒜头切片或者剁成蒜泥都行，备用","group":""},{"text":"辣椒切圈或者斜切成条都行，备用","group":""},{"text":"热锅，锅内放入 10ml - 15ml 食用油。等待 10 秒让油温升高","group":""},{"text":"放入花椒、大蒜爆香（可以吃姜的也可以额外放入一些姜片/姜丝）","group":""},{"text":"加入猪肉炒至变色，再加入 8ml 老抽上色翻炒均匀（有豆瓣酱的，可以放入 3ml 豆瓣酱一起翻炒）","group":""},{"text":"加入香干翻炒均匀（大约 2 分钟）","group":""},{"text":"加入辣椒翻炒均匀（大约 1-2 分钟）","group":""},{"text":"加入芹菜，放入 5g 盐翻炒 1 分钟","group":""},{"text":"加入 3g 鸡精、5ml 蚝油翻炒均匀，即可出锅","group":""}],"tips":["如果没有买到香芹，或者用的芹菜比较粗，可以考虑焯水，放入滚水中 1 分钟捞出，冷水冲洗（保持爽脆）","如果买到的豆干比较硬、紧实，也可以切条后再焯水","香干芹菜炒肉教程"]},
{"id":"xiangganrousi","name":"香干肉丝","category":"荤菜","categoryKey":"meat_dish","emoji":"🍖","color":"#FFB3A7","light":"#FFF0ED","image":null,"hasImage":false,"difficulty":3,"difficultyText":"★★★","calories":"472 大卡","time":"","servings":"1人份","description":"香干肉丝是一道咸香下饭的家常小炒，肉丝嫩滑，香干柔韧，青椒爽脆。富含动物性与植物性双重蛋白质，搭配青椒补充维生素。难度适中，新手稍加练习即可掌握，预计制作时长约 30 分钟。","tags":[],"ingredients":[{"name":"香干","amount":"份数 * 75g","optional":false,"amountValue":75,"amountUnit":"g"},{"name":"青椒的数量","amount":"份数 * 5 个","optional":false,"amountValue":5,"amountUnit":"个"},{"name":"肉量","amount":"份数 * 100g","optional":false,"amountValue":100,"amountUnit":"g"},{"name":"盐量","amount":"份数 * 3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"生抽","amount":"份数 * 5ml","optional":false,"amountValue":5,"amountUnit":"ml"},{"name":"淀粉","amount":"份数 * 5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"大蒜","amount":"份数 * 5g（大约 3 个蒜瓣）","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"鸡精","amount":"2g","optional":false,"amountValue":2,"amountUnit":"g"}],"steps":[{"text":"`肉丝`（没有肉丝，自己切）用生抽(3ml)，生粉混合均匀待用。","group":"准备工作"},{"text":"将`青椒`洗净，再用`滚刀手法`切好备用。","group":"准备工作"},{"text":"`大蒜`横切成片，`香干`切丝。","group":"准备工作"},{"text":"`淀粉`与水(10ml)混合，搅拌均匀。","group":"准备工作"},{"text":"干净锅 15ml 油，不用等油热就倒入肉丝慢慢划散，肉丝熟了，立马捞出，留油到锅里。","group":"起锅"},{"text":"将蒜片和香干放入锅中，加入 2ml 生抽，翻炒均匀。","group":"起锅"},{"text":"2-3 分钟，看火大小，将青椒丝放入锅中混合，翻炒。","group":"起锅"},{"text":"1 分钟后，放入肉丝混合。","group":"起锅"},{"text":"倒入淀粉与水的混合物勾芡，加入盐 3g，鸡精 2g，翻炒 2-3 分钟出锅。","group":"起锅"},{"text":"成品。","group":"起锅"}],"tips":["**辣椒选择青椒，螺丝椒为最优解，喜欢辣的可以加入小米椒切细碎，同青椒一起加入！**"]},
{"id":"xiangguhuaji","name":"香菇滑鸡","category":"荤菜","categoryKey":"meat_dish","emoji":"🍗","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/香菇滑鸡/香菇滑鸡.jpg","hasImage":true,"difficulty":3,"difficultyText":"★★★","calories":"608 大卡","time":"","servings":"1-2人份","description":"香菇滑鸡是一道以鸡腿肉和香菇为主料的家常菜，鸡腿肉经过煸炒和焖煮后口感滑嫩，搭配香菇独特的菌香，汤汁浓郁鲜美，属于老少皆宜的粤式风味。鸡肉富含优质蛋白质和多种氨基酸，香菇含有香菇多糖和膳食纤维，有助于增强免疫力和促进消化。这道菜需要一些刀工和火候控制，对新手有一定挑战，整体制作约需 1 小时。","tags":[],"ingredients":[{"name":"大鸡腿","amount":"2 个","optional":false,"amountValue":2,"amountUnit":"个"},{"name":"干香菇","amount":"5 粒","optional":false,"amountValue":5,"amountUnit":"粒"},{"name":"姜","amount":"2 片","optional":false,"amountValue":2,"amountUnit":"片"},{"name":"葱","amount":"2 颗","optional":false,"amountValue":2,"amountUnit":"颗"},{"name":"蒜","amount":"2 瓣","optional":false,"amountValue":2,"amountUnit":"瓣"},{"name":"温水(30-40 ℃)","amount":"150ml","optional":false,"amountValue":150,"amountUnit":"ml"},{"name":"料酒","amount":"15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"生抽","amount":"30ml","optional":false,"amountValue":30,"amountUnit":"ml"},{"name":"盐","amount":"1.5g","optional":false,"amountValue":1.5,"amountUnit":"g"},{"name":"老抽","amount":"15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"糖","amount":"15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"香油","amount":"5ml","optional":false,"amountValue":5,"amountUnit":"ml"}],"steps":[{"text":"温水泡发干香菇","group":""},{"text":"姜切小块，葱切段，蒜对半切小粒","group":""},{"text":"鸡腿去骨（不去骨也可，只是略影响程序员吃饭的效率而已），切成小块","group":""},{"text":"泡发的香菇一分为四，香菇水留着备用","group":""},{"text":"鸡腿肉焯水 1 分钟，去除血沫和杂质","group":""},{"text":"鸡腿肉中加料酒 15ml、生抽 15ml、盐 1.5g、老抽 15ml，抓匀","group":""},{"text":"油温 3 成，下入鸡腿肉煸炒，等鸡腿肉金黄后盛出备用","group":""},{"text":"锅留底油，下入葱、姜、蒜炒香，香菇入锅，大火翻匀","group":""},{"text":"等待 20 秒会有香菇香味从锅中飘出，此时下入煸炒过的鸡腿肉，下入香菇水（全部，**本程序员认为的灵魂操作**）、糖 15ml、生抽 30ml","group":""},{"text":"转中火不盖盖，咕嘟 2 分钟收浓汤汁，淋入香油 5ml，撒上葱花后即可关火、装盘","group":""}],"tips":["鸡腿去骨操作较复杂，本人经验可供参考：","鸡腿于案板摆正，**骨头正对程序员**，从头部划一刀至最底部，刀口要深，确保有碰到骨头","用手扒拉肉到两边","用刀尖隔开骨头上沾着的肉","鸡腿翻面，刀紧贴骨头插入，挑断骨头与肉的连接点","用刀尖切断最后的粘连即可"]},
{"id":"xiangjianwuhuarou","name":"香煎五花肉","category":"荤菜","categoryKey":"meat_dish","emoji":"🍖","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/香煎五花肉/香煎五花肉.jpg","hasImage":true,"difficulty":3,"difficultyText":"★★★","calories":"2985 大卡","time":"","servings":"1-2人份","description":"香煎五花肉是一道家常风味的快手荤菜，五花肉片煎得焦香微脆、肥而不腻，搭配脆爽的生菜叶和咸鲜豆瓣酱，入口酱香浓郁又解腻。猪肉富含优质蛋白质和脂肪，能快速补充能量，生菜则提供膳食纤维和维生素，营养更均衡。这道菜适合有一定下厨基础的朋友，新手只要注意火候和防溅油也能轻松上手，从备料到出锅大约半小时即可享用。","tags":[],"ingredients":[{"name":"五花肉条（推荐长宽高为","amount":"20cm\\*6cm\\*5cm）","optional":false,"amountValue":null,"amountUnit":""},{"name":"生菜一朵","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"食用油","amount":"5ml","optional":false,"amountValue":5,"amountUnit":"ml"}],"steps":[{"text":"将五花肉条沿长边切片，每片厚 1mm-1.5mm，备用","group":""},{"text":"将切好的五花肉放置碗中，依次加入 8g 酱油，1g 盐，1g 味精，10g 料酒，两片姜，两朵拍扁的大蒜腌制 10 分钟","group":""},{"text":"将生菜叶直接用手扒下来，洗干净，备用","group":""},{"text":"热锅，倒入 5ml 食用油。油轻微冒烟后下入五花肉。单面煎制焦黄色后翻面，另一边同理。","group":""},{"text":"五花肉出锅后，装盘。","group":""},{"text":"将豆瓣酱抹到菜叶上，卷着五花肉即可食用","group":""}],"tips":["操作时，小心被溅出的油烫到"]},
{"id":"xianglajizhuabao","name":"香辣鸡爪煲","category":"荤菜","categoryKey":"meat_dish","emoji":"🍗","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/香辣鸡爪煲/result1.jpg","hasImage":true,"difficulty":4,"difficultyText":"★★★★","calories":"986 大卡","time":"","servings":"1人份","description":"香辣浓郁、口感 Q 弹，是一道常见的家常下饭菜。鸡爪富含胶原蛋白，有助滋润皮肤、强健筋骨。制作需要先去趾甲，若用整只鸡爪还需去骨，对新手略有挑战，但耐心按步骤操作也能成功。从焯水到小火慢煮再翻炒入味，全程约需 45 分钟。","tags":["辣","汤","进阶挑战"],"ingredients":[{"name":"一斤鸡爪","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"香叶","amount":"3 片","optional":false,"amountValue":3,"amountUnit":"片"},{"name":"八角三个","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"小米椒","amount":"6 个","optional":false,"amountValue":6,"amountUnit":"个"},{"name":"姜末","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"蒜末","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"小葱","amount":"2 根","optional":false,"amountValue":2,"amountUnit":"根"},{"name":"蚝油","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"}],"steps":[{"text":"给鸡爪剪去指甲。如果买的鸡爪只有脚掌部分，对半切开即可。 如果是整只鸡爪，需要去骨。清水洗干净。","group":""},{"text":"鸡爪冷水下锅，葱姜料酒焯水，水开，撇去浮沫。","group":""},{"text":"加入香叶、八角、生抽、老抽，盖盖小火慢煮三十分钟。","group":""},{"text":"捞出鸡爪，留一碗鸡汤备用。","group":""},{"text":"起锅烧油，用小火炒香姜末、蒜末、小米椒，能吃辣再放点辣椒面。加入生抽、老抽、蚝油、五香粉、盐，炒出酱香味。","group":""},{"text":"放入鸡爪，放一点盐调味，翻炒一两分钟，再倒入鸡汤，边炒边搅动。","group":""},{"text":"放入鸡精提鲜，撒入葱段搅拌均匀即可出锅。","group":""}],"tips":[]}
];
